// Komori site — собранный файл, не редактировать вручную (исходники в site/src, сборка: node site/build.mjs)
const PAGES = {"main":"<!doctype html>\n<html lang=\"ru\">\n<head>\n<meta charset=\"utf-8\">\n<title>Komori — сервер Minecraft</title>\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<link rel=\"icon\" href=\"/assets/favicon.png\">\n<meta name=\"theme-color\" content=\"#0E0A1A\">\n<style>x-dc{display:none}</style>\n<!--BOOT-->\n<script src=\"/komori-dc.js\" defer></script>\n</head>\n<body>\n<template id=\"komori-tpl\">\n<helmet>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Unbounded:wght@500;700;800&amp;family=Manrope:wght@400;500;600;700&amp;display=swap\">\n<style>\nbody{margin:0;background:#0E0A1A}\na{color:#D9B8FF}a:hover{color:#F3E6FF}\n</style>\n</helmet>\n<div style=\"min-height: 100vh; background: #0E0A1A; color: #EFE8FF; font-family: 'Manrope', system-ui, sans-serif; font-size: 16px; line-height: 1.55\">\n\n<header style=\"position: sticky; top: 0; z-index: 10; background: #08060F; border-bottom: 1px solid #241A40\">\n<div style=\"max-width: 1240px; margin: 0 auto; padding: 12px 24px; display: flex; flex-wrap: wrap; align-items: center; gap: 12px 28px\">\n<a href=\"/\" style=\"display: flex; align-items: center; gap: 12px; text-decoration: none; color: #F3E6FF\">\n<img src=\"/assets/logo.png\" alt=\"Логотип Komori\" style=\"height: 44px; width: 44px; display: block\">\n<span style=\"font-family: 'Unbounded', sans-serif; font-weight: 800; font-size: 22px; letter-spacing: 0.04em\">KOMORI</span>\n</a>\n<nav aria-label=\"Основное меню\" style=\"display: flex; flex-wrap: wrap; gap: 4px; flex: 1 1 420px\">\n<template data-sc=\"for\" list=\"{{K.nav}}\" as=\"n\">\n<a href=\"{{n.href}}\" aria-current=\"{{n.current}}\" style=\"padding: 10px 14px; border-radius: 8px; text-decoration: none; color: {{n.color}}; background: {{n.bg}}; font-weight: 700\">{{n.label}}</a>\n</template>\n</nav>\n<div style=\"display: flex; flex-wrap: wrap; gap: 10px; align-items: center\">\n<template data-sc=\"if\" value=\"{{K.loggedIn}}\">\n<a href=\"/profile\" style=\"display: flex; align-items: center; gap: 10px; padding: 6px 14px 6px 6px; min-height: 44px; box-sizing: border-box; border-radius: 10px; border: 1px solid #2E2250; background: #170F2B; color: #EFE8FF; text-decoration: none; font-weight: 700\">\n<img src=\"{{K.avatar}}\" alt=\"\" width=\"32\" height=\"32\" style=\"width: 32px; height: 32px; border-radius: 50%; display: block; background: #2A1E4A\">\n{{K.name}}\n</a>\n<button type=\"button\" onClick=\"{{K.logout}}\" style=\"padding: 11px 14px; min-height: 44px; border-radius: 10px; border: 1px solid #2E2250; background: transparent; color: #FF9FB8; font: inherit; font-weight: 700; cursor: pointer\">Выйти</button>\n</template>\n<template data-sc=\"if\" value=\"{{K.loggedOut}}\">\n<a href=\"{{K.loginUrl}}\" style=\"display: flex; align-items: center; gap: 8px; padding: 11px 18px; min-height: 44px; box-sizing: border-box; border-radius: 10px; background: #5865F2; color: #FFFFFF; text-decoration: none; font-weight: 700\">\n<svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4\"></path><path d=\"M10 17l5-5-5-5\"></path><path d=\"M15 12H3\"></path></svg>\nВойти через Discord\n</a>\n</template>\n</div>\n</div>\n<template data-sc=\"if\" value=\"{{K.flash}}\">\n<div role=\"status\" style=\"max-width: 1240px; margin: 0 auto 12px; padding: 12px 24px\">\n<div style=\"padding: 12px 16px; border-radius: 10px; background: #3A2A10; color: #FFD48A; font-weight: 600\">{{K.flash}} <template data-sc=\"if\" value=\"{{K.flashJoin}}\"><a href=\"{{K.discord}}\" target=\"_blank\" rel=\"noopener\" style=\"color: #FFFFFF\">Зайти на сервер Discord</a></template></div>\n</div>\n</template>\n</header>\n\n<section id=\"top\" style=\"max-width: 1240px; margin: 0 auto; padding: 80px 24px 72px; display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 48px; align-items: center\">\n<div style=\"display: flex; flex-direction: column; gap: 24px\">\n<span style=\"align-self: flex-start; padding: 6px 12px; border-radius: 999px; background: #1F1638; color: {{statusColor}}; font-weight: 600; font-size: 14px\">{{statusText}}</span>\n<h1 style=\"margin: 0; font-family: 'Unbounded', sans-serif; font-weight: 800; font-size: clamp(44px, 6.5vw, 76px); line-height: 1.02; color: #FFFFFF\">KOMORI</h1>\n<p style=\"margin: 0; font-size: 20px; color: #C7BBE6; max-width: 520px\">Выживание с кастомными предметами, своими зачарованиями, рыбалкой и новыми биомами.</p>\n<div style=\"display: flex; flex-wrap: wrap; gap: 12px\">\n<a href=\"#how\" style=\"padding: 14px 24px; min-height: 48px; box-sizing: border-box; border-radius: 10px; background: #8B3DFF; color: #FFFFFF; text-decoration: none; font-weight: 700\">Начать играть</a>\n<a href=\"{{K.launcher}}\" style=\"padding: 14px 24px; min-height: 48px; box-sizing: border-box; border-radius: 10px; background: #1F1638; color: #EFE8FF; text-decoration: none; font-weight: 600\">Скачать лаунчер</a>\n<a href=\"{{K.discord}}\" target=\"_blank\" rel=\"noopener\" style=\"padding: 14px 24px; min-height: 48px; box-sizing: border-box; border-radius: 10px; background: #5865F2; color: #FFFFFF; text-decoration: none; font-weight: 700\">Наш Discord</a>\n</div>\n<div style=\"background: #170F2B; border: 1px solid #2E2250; border-radius: 14px; padding: 18px; display: flex; flex-direction: column; gap: 12px; max-width: 520px\">\n<div style=\"font-size: 13px; color: #B9AED6; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em\">IP для подключения</div>\n<div style=\"display: flex; flex-wrap: wrap; gap: 10px; align-items: center\">\n<code style=\"flex: 1 1 200px; padding: 12px 16px; border-radius: 10px; background: #08060F; color: #FFFFFF; font-family: 'Unbounded', monospace; font-size: 17px\">mc.komori.fun</code>\n<button type=\"button\" onClick=\"{{copy}}\" style=\"padding: 12px 18px; min-height: 48px; border-radius: 10px; border: none; background: #8B3DFF; color: #FFFFFF; font: inherit; font-weight: 700; cursor: pointer\">{{copyLabel}}</button>\n</div>\n</div>\n</div>\n<div style=\"display: flex; flex-direction: column; gap: 14px\">\n<img src=\"/assets/hero.jpg\" alt=\"Летучая мышь — талисман Komori\" style=\"width: 100%; aspect-ratio: 16 / 10; object-fit: cover; border-radius: 18px; border: 1px solid #2E2250; display: block\">\n<div style=\"display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px\">\n<div style=\"background: #170F2B; border-radius: 12px; padding: 14px\">\n<div style=\"font-family: 'Unbounded', sans-serif; font-size: 22px; font-weight: 700; color: #FFFFFF\">{{online}}</div>\n<div style=\"font-size: 13px; color: #B9AED6\">игроков онлайн</div>\n</div>\n<div style=\"background: #170F2B; border-radius: 12px; padding: 14px\">\n<div style=\"font-family: 'Unbounded', sans-serif; font-size: 22px; font-weight: 700; color: #FFFFFF\">26.2</div>\n<div style=\"font-size: 13px; color: #B9AED6\">версия</div>\n</div>\n<div style=\"background: #170F2B; border-radius: 12px; padding: 14px\">\n<div style=\"font-family: 'Unbounded', sans-serif; font-size: 22px; font-weight: 700; color: #FFFFFF\">{{discordMembers}}</div>\n<div style=\"font-size: 13px; color: #B9AED6\">в Discord</div>\n</div>\n</div>\n</div>\n</section>\n\n<section id=\"news\" style=\"max-width: 1240px; margin: 0 auto; padding: 0 24px 72px; display: flex; flex-direction: column; gap: 24px\">\n<h2 style=\"margin: 0; font-family: 'Unbounded', sans-serif; font-weight: 700; font-size: 32px; color: #FFFFFF\">Новости</h2>\n<a href=\"#news\" style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 0; background: #170F2B; border: 1px solid #2E2250; border-radius: 18px; overflow: hidden; text-decoration: none; color: #EFE8FF\">\n<img src=\"/assets/hero.jpg\" alt=\"Fishing Update\" style=\"width: 100%; height: 100%; min-height: 240px; object-fit: cover; display: block\">\n<div style=\"padding: 32px; display: flex; flex-direction: column; gap: 12px; justify-content: center\">\n<span style=\"align-self: flex-start; padding: 4px 10px; border-radius: 999px; background: #8B3DFF; color: #FFFFFF; font-size: 13px; font-weight: 700\">Скоро</span>\n<h3 style=\"margin: 0; font-family: 'Unbounded', sans-serif; font-size: 26px; color: #FFFFFF\">Обновление рыбалки</h3>\n<p style=\"margin: 0; color: #C7BBE6\">Мини-игра при поклёвке, сокровища, каталог рыб и уловы, которые зависят от биома.</p>\n<span style=\"color: #D9B8FF; font-weight: 700\">Читать подробнее →</span>\n</div>\n</a>\n</section>\n\n<section style=\"background: #130D24; border-top: 1px solid #241A40; border-bottom: 1px solid #241A40\">\n<div style=\"max-width: 1240px; margin: 0 auto; padding: 72px 24px; display: flex; flex-direction: column; gap: 32px\">\n<h2 style=\"margin: 0; font-family: 'Unbounded', sans-serif; font-weight: 700; font-size: 32px; color: #FFFFFF\">Что есть на сервере</h2>\n<div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 16px\">\n<div style=\"background: #1F1638; border-radius: 14px; padding: 24px; display: flex; flex-direction: column; gap: 10px\">\n<svg width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#B57BFF\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M4 19.5A2.5 2.5 0 0 1 6.5 17H20V3H6.5A2.5 2.5 0 0 0 4 5.5z\"></path><path d=\"M12 7v6M9 10h6\"></path></svg>\n<h3 style=\"margin: 0; font-size: 19px; color: #FFFFFF\">Свои предметы и зачарования</h3>\n<p style=\"margin: 0; color: #C7BBE6\">Уникальные зачарованные книги, проклятия и кастомные предметы, которых нет в ванилле.</p>\n</div>\n<div style=\"background: #1F1638; border-radius: 14px; padding: 24px; display: flex; flex-direction: column; gap: 10px\">\n<svg width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#B57BFF\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 20l6-10 4 6 3-4 5 8z\"></path><circle cx=\"17\" cy=\"6\" r=\"2\"></circle></svg>\n<h3 style=\"margin: 0; font-size: 19px; color: #FFFFFF\">Новые биомы</h3>\n<p style=\"margin: 0; color: #C7BBE6\">Мир с генерацией Terralith: горы, снежные долины и десятки необычных биомов.</p>\n</div>\n<div style=\"background: #1F1638; border-radius: 14px; padding: 24px; display: flex; flex-direction: column; gap: 10px\">\n<svg width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#B57BFF\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 12c4-6 12-6 16 0-4 6-12 6-16 0z\"></path><path d=\"M19 12l3-3v6z\"></path></svg>\n<h3 style=\"margin: 0; font-size: 19px; color: #FFFFFF\">Рыбалка <span style=\"font-size: 13px; color: #9FE3B4\">скоро</span></h3>\n<p style=\"margin: 0; color: #C7BBE6\">Мини-игра, сокровища и редкие рыбы, которые зависят от биома.</p>\n</div>\n<div style=\"background: #1F1638; border-radius: 14px; padding: 24px; display: flex; flex-direction: column; gap: 10px\">\n<svg width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#B57BFF\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M8 21h8M12 17v4M7 4h10v5a5 5 0 0 1-10 0z\"></path><path d=\"M17 5h3v2a3 3 0 0 1-3 3M7 5H4v2a3 3 0 0 0 3 3\"></path></svg>\n<h3 style=\"margin: 0; font-size: 19px; color: #FFFFFF\">Топы игроков</h3>\n<p style=\"margin: 0; color: #C7BBE6\">Соревнуйся в топе охотников и других рейтингах сервера.</p>\n</div>\n</div>\n</div>\n</section>\n\n<section id=\"how\" style=\"max-width: 1240px; margin: 0 auto; padding: 72px 24px; display: flex; flex-direction: column; gap: 32px\">\n<h2 style=\"margin: 0; font-family: 'Unbounded', sans-serif; font-weight: 700; font-size: 32px; color: #FFFFFF\">Как начать играть</h2>\n<div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 16px\">\n<div style=\"border: 1px solid #2E2250; border-radius: 14px; padding: 24px; display: flex; flex-direction: column; gap: 8px\">\n<span style=\"font-family: 'Unbounded', sans-serif; font-size: 32px; font-weight: 800; color: #B57BFF\">1</span>\n<h3 style=\"margin: 0; font-size: 18px; color: #FFFFFF\">Скачай Komori Launcher</h3>\n<p style=\"margin: 0; color: #C7BBE6\">Войди через Microsoft и нажми «Играть на Komori» — лаунчер сам поставит нужную версию и моды. <a href=\"{{K.launcher}}\">Скачать для Windows</a></p>\n</div>\n<div style=\"border: 1px solid #2E2250; border-radius: 14px; padding: 24px; display: flex; flex-direction: column; gap: 8px\">\n<span style=\"font-family: 'Unbounded', sans-serif; font-size: 32px; font-weight: 800; color: #B57BFF\">2</span>\n<h3 style=\"margin: 0; font-size: 18px; color: #FFFFFF\">Или добавь сервер вручную</h3>\n<p style=\"margin: 0; color: #C7BBE6\">Minecraft 26.2 → Сетевая игра → Добавить → вставь IP mc.komori.fun.</p>\n</div>\n<div style=\"border: 1px solid #2E2250; border-radius: 14px; padding: 24px; display: flex; flex-direction: column; gap: 8px\">\n<span style=\"font-family: 'Unbounded', sans-serif; font-size: 32px; font-weight: 800; color: #B57BFF\">3</span>\n<h3 style=\"margin: 0; font-size: 18px; color: #FFFFFF\">Прими ресурспак</h3>\n<p style=\"margin: 0; color: #C7BBE6\">Без него не будут видны текстуры кастомных предметов.</p>\n</div>\n</div>\n</section>\n\n\n<footer style=\"background: #08060F; border-top: 1px solid #241A40\">\n<div style=\"max-width: 1240px; margin: 0 auto; padding: 32px 24px; display: flex; flex-wrap: wrap; gap: 16px; justify-content: space-between; color: #B9AED6; font-size: 14px\">\n<span>© 2026 Komori · mc.komori.fun · Не связан с Mojang и Microsoft.</span>\n<span style=\"display: flex; gap: 20px; flex-wrap: wrap\"><a href=\"/rules\">Правила</a><a href=\"/wiki\">Вики</a><a href=\"/map\">Карта</a><a href=\"{{K.launcher}}\">Лаунчер</a><a href=\"{{K.discord}}\" target=\"_blank\" rel=\"noopener\">Discord</a></span>\n</div>\n</footer>\n\n</div>\n</template><x-dc></x-dc>\n<script type=\"text/x-dc\" data-dc-script>\nclass Component extends DCLogic {\nconstructor(props) {\nsuper(props);\nthis.state = { copied: false, stats: null };\n}\nmounted() {\nvar self = this;\nfetch('/api/stats').then(function (r) { return r.json(); }).then(function (d) { self.setState({ stats: d }); }).catch(function () {});\n}\nrenderVals() {\nvar self = this, st = this.state.stats, mc = st && st.mc, dc = st && st.discord;\nreturn {\nstatusText: !st ? '● Проверяем сервер…' : mc && mc.online ? '● Сервер онлайн · версия 26.2' : '● Сервер сейчас недоступен',\nstatusColor: !st || (mc && mc.online) ? '#9FE3B4' : '#FF9FB8',\nonline: mc && mc.online ? mc.players + ' / ' + mc.max : '—',\ndiscordMembers: dc ? dc.members : '—',\ncopyLabel: this.state.copied ? 'Скопировано' : 'Копировать',\ncopy: function () {\ntry { navigator.clipboard.writeText('mc.komori.fun'); } catch (e) {}\nself.setState({ copied: true });\nsetTimeout(function () { self.setState({ copied: false }); }, 1600);\n}\n};\n}\n}\n</script>\n</body>\n</html>\n","map":"<!doctype html>\n<html lang=\"ru\">\n<head>\n<meta charset=\"utf-8\">\n<title>Карта — Komori</title>\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<link rel=\"icon\" href=\"/assets/favicon.png\">\n<meta name=\"theme-color\" content=\"#0E0A1A\">\n<style>x-dc{display:none}</style>\n<!--BOOT-->\n<script src=\"/komori-dc.js\" defer></script>\n</head>\n<body>\n<template id=\"komori-tpl\">\n<helmet>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Unbounded:wght@500;700;800&amp;family=Manrope:wght@400;500;600;700&amp;display=swap\">\n<style>\nbody{margin:0;background:#0E0A1A}\na{color:#D9B8FF}a:hover{color:#F3E6FF}\n</style>\n</helmet>\n<div style=\"min-height: 100vh; background: #0E0A1A; color: #EFE8FF; font-family: 'Manrope', system-ui, sans-serif; font-size: 16px; line-height: 1.55; display: flex; flex-direction: column\">\n<header style=\"position: sticky; top: 0; z-index: 10; background: #08060F; border-bottom: 1px solid #241A40\">\n<div style=\"max-width: 1240px; margin: 0 auto; padding: 12px 24px; display: flex; flex-wrap: wrap; align-items: center; gap: 12px 28px\">\n<a href=\"/\" style=\"display: flex; align-items: center; gap: 12px; text-decoration: none; color: #F3E6FF\">\n<img src=\"/assets/logo.png\" alt=\"Логотип Komori\" style=\"height: 44px; width: 44px; display: block\">\n<span style=\"font-family: 'Unbounded', sans-serif; font-weight: 800; font-size: 22px; letter-spacing: 0.04em\">KOMORI</span>\n</a>\n<nav aria-label=\"Основное меню\" style=\"display: flex; flex-wrap: wrap; gap: 4px; flex: 1 1 420px\">\n<template data-sc=\"for\" list=\"{{K.nav}}\" as=\"n\">\n<a href=\"{{n.href}}\" aria-current=\"{{n.current}}\" style=\"padding: 10px 14px; border-radius: 8px; text-decoration: none; color: {{n.color}}; background: {{n.bg}}; font-weight: 700\">{{n.label}}</a>\n</template>\n</nav>\n<div style=\"display: flex; flex-wrap: wrap; gap: 10px; align-items: center\">\n<template data-sc=\"if\" value=\"{{K.loggedIn}}\">\n<a href=\"/profile\" style=\"display: flex; align-items: center; gap: 10px; padding: 6px 14px 6px 6px; min-height: 44px; box-sizing: border-box; border-radius: 10px; border: 1px solid #2E2250; background: #170F2B; color: #EFE8FF; text-decoration: none; font-weight: 700\">\n<img src=\"{{K.avatar}}\" alt=\"\" width=\"32\" height=\"32\" style=\"width: 32px; height: 32px; border-radius: 50%; display: block; background: #2A1E4A\">\n{{K.name}}\n</a>\n<button type=\"button\" onClick=\"{{K.logout}}\" style=\"padding: 11px 14px; min-height: 44px; border-radius: 10px; border: 1px solid #2E2250; background: transparent; color: #FF9FB8; font: inherit; font-weight: 700; cursor: pointer\">Выйти</button>\n</template>\n<template data-sc=\"if\" value=\"{{K.loggedOut}}\">\n<a href=\"{{K.loginUrl}}\" style=\"display: flex; align-items: center; gap: 8px; padding: 11px 18px; min-height: 44px; box-sizing: border-box; border-radius: 10px; background: #5865F2; color: #FFFFFF; text-decoration: none; font-weight: 700\">\n<svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4\"></path><path d=\"M10 17l5-5-5-5\"></path><path d=\"M15 12H3\"></path></svg>\nВойти через Discord\n</a>\n</template>\n</div>\n</div>\n<template data-sc=\"if\" value=\"{{K.flash}}\">\n<div role=\"status\" style=\"max-width: 1240px; margin: 0 auto 12px; padding: 12px 24px\">\n<div style=\"padding: 12px 16px; border-radius: 10px; background: #3A2A10; color: #FFD48A; font-weight: 600\">{{K.flash}} <template data-sc=\"if\" value=\"{{K.flashJoin}}\"><a href=\"{{K.discord}}\" target=\"_blank\" rel=\"noopener\" style=\"color: #FFFFFF\">Зайти на сервер Discord</a></template></div>\n</div>\n</template>\n</header>\n\n<section style=\"flex: 1; max-width: 1240px; width: 100%; box-sizing: border-box; margin: 0 auto; padding: 48px 24px 72px; display: flex; flex-direction: column; gap: 24px\">\n<h1 style=\"margin: 0; font-family: 'Unbounded', sans-serif; font-weight: 800; font-size: clamp(32px, 5vw, 48px); color: #FFFFFF\">Карта мира</h1>\n<p style=\"margin: 0; color: #C7BBE6; max-width: 720px\">Живая карта сервера: смотри, где стоят постройки, ищи биомы и следи, кто из игроков сейчас онлайн.</p>\n\n<div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 16px; align-items: stretch\">\n<div style=\"background: #170F2B; border: 1px solid #2E2250; border-radius: 18px; overflow: hidden; display: flex; flex-direction: column\">\n<img src=\"/assets/hero.jpg\" alt=\"\" style=\"width: 100%; height: 220px; object-fit: cover; display: block; opacity: 0.85\">\n<div style=\"padding: 24px; display: flex; flex-direction: column; gap: 14px\">\n<h2 style=\"margin: 0; font-size: 20px; color: #FFFFFF\">Обычный мир</h2>\n<p style=\"margin: 0; color: #C7BBE6\">Карта открывается в новой вкладке. Колёсиком мыши — приближение, слева — список игроков онлайн.</p>\n<a href=\"{{K.map}}\" target=\"_blank\" rel=\"noopener\" style=\"align-self: flex-start; display: flex; align-items: center; gap: 8px; padding: 14px 22px; min-height: 48px; box-sizing: border-box; border-radius: 12px; background: #8B3DFF; color: #FFFFFF; text-decoration: none; font-weight: 800\">\n<svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M9 4L3 6v14l6-2 6 2 6-2V4l-6 2z\"></path><path d=\"M9 4v14M15 6v14\"></path></svg>\nОткрыть карту\n</a>\n</div>\n</div>\n\n<div style=\"background: #170F2B; border: 1px solid #2E2250; border-radius: 18px; padding: 24px; display: flex; flex-direction: column; gap: 14px\">\n<h2 style=\"margin: 0; font-size: 20px; color: #FFFFFF\">Сейчас на сервере</h2>\n<span style=\"color: #B9AED6\">{{onlineLine}}</span>\n<div style=\"display: flex; flex-wrap: wrap; gap: 8px\">\n<template data-sc=\"for\" list=\"{{players}}\" as=\"p\">\n<span style=\"display: flex; align-items: center; gap: 8px; padding: 6px 12px 6px 6px; border-radius: 10px; background: #1F1638; color: #EFE8FF; font-weight: 600\">\n<img src=\"{{p.head}}\" alt=\"\" width=\"24\" height=\"24\" style=\"width: 24px; height: 24px; border-radius: 4px; image-rendering: pixelated; display: block\">{{p.name}}\n</span>\n</template>\n</div>\n</div>\n</div>\n</section>\n\n<footer style=\"background: #08060F; border-top: 1px solid #241A40\">\n<div style=\"max-width: 1240px; margin: 0 auto; padding: 32px 24px; display: flex; flex-wrap: wrap; gap: 16px; justify-content: space-between; color: #B9AED6; font-size: 14px\">\n<span>© 2026 Komori · mc.komori.fun · Не связан с Mojang и Microsoft.</span>\n<span style=\"display: flex; gap: 20px; flex-wrap: wrap\"><a href=\"/rules\">Правила</a><a href=\"/wiki\">Вики</a><a href=\"/map\">Карта</a><a href=\"{{K.launcher}}\">Лаунчер</a><a href=\"{{K.discord}}\" target=\"_blank\" rel=\"noopener\">Discord</a></span>\n</div>\n</footer>\n</div>\n</template><x-dc></x-dc>\n<script type=\"text/x-dc\" data-dc-script>\nclass Component extends DCLogic {\nconstructor(props) {\nsuper(props);\nthis.state = { stats: null };\n}\nmounted() {\nvar self = this;\nfetch('/api/stats').then(function (r) { return r.json(); }).then(function (d) { self.setState({ stats: d }); }).catch(function () {});\n}\nrenderVals() {\nvar st = this.state.stats, mc = st && st.mc;\nvar list = (mc && mc.list) || [];\nreturn {\nonlineLine: !st ? 'Проверяем сервер…' : !mc || !mc.online ? 'Сервер сейчас недоступен' : mc.players === 0 ? 'Пока никого нет — заходи первым!' : 'Игроков онлайн: ' + mc.players + ' из ' + mc.max,\nplayers: list.map(function (n) { return { name: n, head: 'https://mc-heads.net/avatar/' + encodeURIComponent(n) + '/24' }; })\n};\n}\n}\n</script>\n</body>\n</html>\n","profile":"<!doctype html>\n<html lang=\"ru\">\n<head>\n<meta charset=\"utf-8\">\n<title>Профиль — Komori</title>\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<link rel=\"icon\" href=\"/assets/favicon.png\">\n<meta name=\"theme-color\" content=\"#0E0A1A\">\n<style>x-dc{display:none}</style>\n<!--BOOT-->\n<script src=\"/komori-dc.js\" defer></script>\n</head>\n<body>\n<template id=\"komori-tpl\">\n<helmet>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Unbounded:wght@500;700;800&amp;family=Manrope:wght@400;500;600;700&amp;display=swap\">\n<style>\nbody{margin:0;background:#0E0A1A}\na{color:#D9B8FF}a:hover{color:#F3E6FF}\n</style>\n</helmet>\n<div style=\"min-height: 100vh; background: #0E0A1A; color: #EFE8FF; font-family: 'Manrope', system-ui, sans-serif; font-size: 16px; line-height: 1.55; display: flex; flex-direction: column\">\n<header style=\"position: sticky; top: 0; z-index: 10; background: #08060F; border-bottom: 1px solid #241A40\">\n<div style=\"max-width: 1240px; margin: 0 auto; padding: 12px 24px; display: flex; flex-wrap: wrap; align-items: center; gap: 12px 28px\">\n<a href=\"/\" style=\"display: flex; align-items: center; gap: 12px; text-decoration: none; color: #F3E6FF\">\n<img src=\"/assets/logo.png\" alt=\"Логотип Komori\" style=\"height: 44px; width: 44px; display: block\">\n<span style=\"font-family: 'Unbounded', sans-serif; font-weight: 800; font-size: 22px; letter-spacing: 0.04em\">KOMORI</span>\n</a>\n<nav aria-label=\"Основное меню\" style=\"display: flex; flex-wrap: wrap; gap: 4px; flex: 1 1 420px\">\n<template data-sc=\"for\" list=\"{{K.nav}}\" as=\"n\">\n<a href=\"{{n.href}}\" aria-current=\"{{n.current}}\" style=\"padding: 10px 14px; border-radius: 8px; text-decoration: none; color: {{n.color}}; background: {{n.bg}}; font-weight: 700\">{{n.label}}</a>\n</template>\n</nav>\n<div style=\"display: flex; flex-wrap: wrap; gap: 10px; align-items: center\">\n<template data-sc=\"if\" value=\"{{K.loggedIn}}\">\n<a href=\"/profile\" style=\"display: flex; align-items: center; gap: 10px; padding: 6px 14px 6px 6px; min-height: 44px; box-sizing: border-box; border-radius: 10px; border: 1px solid #2E2250; background: #170F2B; color: #EFE8FF; text-decoration: none; font-weight: 700\">\n<img src=\"{{K.avatar}}\" alt=\"\" width=\"32\" height=\"32\" style=\"width: 32px; height: 32px; border-radius: 50%; display: block; background: #2A1E4A\">\n{{K.name}}\n</a>\n<button type=\"button\" onClick=\"{{K.logout}}\" style=\"padding: 11px 14px; min-height: 44px; border-radius: 10px; border: 1px solid #2E2250; background: transparent; color: #FF9FB8; font: inherit; font-weight: 700; cursor: pointer\">Выйти</button>\n</template>\n<template data-sc=\"if\" value=\"{{K.loggedOut}}\">\n<a href=\"{{K.loginUrl}}\" style=\"display: flex; align-items: center; gap: 8px; padding: 11px 18px; min-height: 44px; box-sizing: border-box; border-radius: 10px; background: #5865F2; color: #FFFFFF; text-decoration: none; font-weight: 700\">\n<svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4\"></path><path d=\"M10 17l5-5-5-5\"></path><path d=\"M15 12H3\"></path></svg>\nВойти через Discord\n</a>\n</template>\n</div>\n</div>\n<template data-sc=\"if\" value=\"{{K.flash}}\">\n<div role=\"status\" style=\"max-width: 1240px; margin: 0 auto 12px; padding: 12px 24px\">\n<div style=\"padding: 12px 16px; border-radius: 10px; background: #3A2A10; color: #FFD48A; font-weight: 600\">{{K.flash}} <template data-sc=\"if\" value=\"{{K.flashJoin}}\"><a href=\"{{K.discord}}\" target=\"_blank\" rel=\"noopener\" style=\"color: #FFFFFF\">Зайти на сервер Discord</a></template></div>\n</div>\n</template>\n</header>\n\n<template data-sc=\"if\" value=\"{{loading}}\">\n<section style=\"flex: 1; max-width: 1240px; width: 100%; box-sizing: border-box; margin: 0 auto; padding: 64px 24px; color: #B9AED6\">Загружаю профиль…</section>\n</template>\n\n<template data-sc=\"if\" value=\"{{notFound}}\">\n<section style=\"flex: 1; max-width: 1240px; width: 100%; box-sizing: border-box; margin: 0 auto; padding: 64px 24px; display: flex; flex-direction: column; gap: 16px; align-items: flex-start\">\n<h1 style=\"margin: 0; font-family: 'Unbounded', sans-serif; font-size: 30px; color: #FFFFFF\">{{notFoundTitle}}</h1>\n<p style=\"margin: 0; color: #C7BBE6\">{{notFoundText}}</p>\n<template data-sc=\"if\" value=\"{{K.loggedOut}}\">\n<a href=\"{{K.loginUrl}}\" style=\"padding: 14px 22px; border-radius: 12px; background: #5865F2; color: #FFFFFF; text-decoration: none; font-weight: 800\">Войти через Discord</a>\n</template>\n</section>\n</template>\n\n<template data-sc=\"if\" value=\"{{ready}}\">\n<section style=\"max-width: 1240px; width: 100%; box-sizing: border-box; margin: 0 auto; padding: 28px 24px 0\">\n<div style=\"position: relative; border-radius: 20px; overflow: hidden; border: 2px solid {{accent}}; background: #170F2B\">\n<img src=\"/assets/hero.jpg\" alt=\"Баннер профиля\" style=\"width: 100%; height: 220px; object-fit: cover; display: block\">\n<div style=\"padding: 0 28px 24px; display: flex; flex-wrap: wrap; gap: 20px; align-items: flex-end; margin-top: -64px; position: relative\">\n<img src=\"{{p.avatar}}\" alt=\"Аватар {{p.name}}\" width=\"128\" height=\"128\" style=\"width: 128px; height: 128px; border-radius: 22px; background: #2A1E4A; border: 5px solid {{accent}}; box-shadow: 0 0 0 5px #170F2B; display: block; object-fit: cover\">\n<div style=\"flex: 1 1 260px; display: flex; flex-direction: column; gap: 6px; padding-bottom: 6px\">\n<div style=\"display: flex; flex-wrap: wrap; align-items: center; gap: 10px\">\n<span style=\"font-family: 'Unbounded', sans-serif; font-size: 28px; font-weight: 800; color: #FFFFFF\">{{p.name}}</span>\n<template data-sc=\"for\" list=\"{{badges}}\" as=\"b\">\n<span style=\"padding: 3px 12px; border-radius: 999px; border: 1px solid {{b.color}}; color: {{b.color}}; font-size: 13px; font-weight: 700\">{{b.label}}</span>\n</template>\n</div>\n<span style=\"color: #D9CCF5\">{{statusShown}}</span>\n</div>\n<div style=\"display: flex; flex-wrap: wrap; gap: 10px; padding-bottom: 6px\">\n<template data-sc=\"if\" value=\"{{own}}\">\n<button type=\"button\" onClick=\"{{toggleEdit}}\" style=\"padding: 12px 18px; min-height: 44px; border-radius: 10px; border: none; background: #8B3DFF; color: #FFFFFF; font: inherit; font-weight: 700; cursor: pointer\">{{editLabel}}</button>\n</template>\n<button type=\"button\" onClick=\"{{share}}\" style=\"padding: 12px 18px; min-height: 44px; border-radius: 10px; border: 1px solid #2E2250; background: #1F1638; color: #EFE8FF; font: inherit; font-weight: 700; cursor: pointer\">{{shareLabel}}</button>\n</div>\n</div>\n</div>\n</section>\n\n<section style=\"flex: 1; max-width: 1240px; width: 100%; box-sizing: border-box; margin: 0 auto; padding: 24px 24px 80px; display: flex; flex-direction: column; gap: 20px\">\n\n<template data-sc=\"if\" value=\"{{viewing}}\">\n<div style=\"background: #170F2B; border: 1px solid #2E2250; border-radius: 18px; padding: 24px; display: flex; flex-direction: column; gap: 12px\">\n<h2 style=\"margin: 0; font-size: 18px; color: #FFFFFF\">О себе</h2>\n<p style=\"margin: 0; color: #E2DAF5; white-space: pre-line\">{{bioShown}}</p>\n<div style=\"display: flex; flex-wrap: wrap; gap: 8px; margin-top: 6px\">\n<span style=\"padding: 6px 12px; border-radius: 10px; background: #1F1638; color: #C7BBE6; font-size: 14px\">На сайте с {{p.since}}</span>\n<template data-sc=\"if\" value=\"{{p.discordTag}}\"><span style=\"padding: 6px 12px; border-radius: 10px; background: #1F1638; color: #C7BBE6; font-size: 14px\">Discord: {{p.discordTag}}</span></template>\n<template data-sc=\"for\" list=\"{{linkList}}\" as=\"l\">\n<a href=\"{{l.url}}\" target=\"_blank\" rel=\"noopener nofollow ugc\" style=\"padding: 6px 12px; border-radius: 10px; background: #1F1638; color: #D9B8FF; font-size: 14px; text-decoration: none\">{{l.label}}</a>\n</template>\n</div>\n</div>\n</template>\n\n<template data-sc=\"if\" value=\"{{editing}}\">\n<div style=\"display: flex; flex-direction: column; gap: 20px\">\n<h1 style=\"margin: 0; font-family: 'Unbounded', sans-serif; font-size: 30px; color: #FFFFFF\">Настройки профиля</h1>\n<p style=\"margin: 0; color: #C7BBE6\">Аватарка и ник берутся из Discord. Профиль видят все — правила сервера действуют и здесь.</p>\n\n<div style=\"background: #170F2B; border: 1px solid #2E2250; border-radius: 18px; padding: 22px; display: flex; flex-direction: column; gap: 16px\">\n<div style=\"display: flex; flex-direction: column; gap: 6px\">\n<label for=\"status\" style=\"font-weight: 700; color: #FFFFFF\">Статус</label>\n<input id=\"status\" type=\"text\" maxlength=\"60\" value=\"{{f.status}}\" onInput=\"{{onStatus}}\" placeholder=\"Коротко: чем занят сейчас\" style=\"padding: 12px 14px; min-height: 44px; box-sizing: border-box; border-radius: 10px; border: 1px solid #2E2250; background: #0E0A1A; color: #FFFFFF; font: inherit\">\n<span style=\"align-self: flex-end; font-size: 13px; color: #B9AED6\">{{statusCount}} / 60</span>\n</div>\n<div style=\"display: flex; flex-direction: column; gap: 6px\">\n<label for=\"bio\" style=\"font-weight: 700; color: #FFFFFF\">О себе</label>\n<textarea id=\"bio\" rows=\"5\" maxlength=\"300\" onInput=\"{{onBio}}\" placeholder=\"Расскажи о себе: во что играешь, что строишь, кого ищешь в команду\" style=\"padding: 12px 14px; border-radius: 10px; border: 1px solid #2E2250; background: #0E0A1A; color: #FFFFFF; font: inherit; resize: vertical\">{{f.bio}}</textarea>\n<span style=\"align-self: flex-end; font-size: 13px; color: #B9AED6\">{{bioCount}} / 300</span>\n</div>\n</div>\n\n<div style=\"background: #170F2B; border: 1px solid #2E2250; border-radius: 18px; padding: 22px; display: flex; flex-direction: column; gap: 14px\">\n<h2 style=\"margin: 0; font-size: 18px; color: #FFFFFF\">Цвет профиля</h2>\n<div role=\"radiogroup\" aria-label=\"Цвет профиля\" style=\"display: flex; flex-wrap: wrap; gap: 10px\">\n<template data-sc=\"for\" list=\"{{colors}}\" as=\"c\">\n<button type=\"button\" role=\"radio\" aria-checked=\"{{c.on}}\" aria-label=\"{{c.name}}\" onClick=\"{{c.pick}}\" style=\"width: 48px; height: 48px; border-radius: 12px; border: 3px solid {{c.ring}}; background: {{c.hex}}; cursor: pointer\"></button>\n</template>\n</div>\n<span style=\"font-size: 14px; color: #B9AED6\">Цвет рамки профиля и аватарки.</span>\n</div>\n\n<div style=\"background: #170F2B; border: 1px solid #2E2250; border-radius: 18px; padding: 22px; display: flex; flex-direction: column; gap: 14px\">\n<h2 style=\"margin: 0; font-size: 18px; color: #FFFFFF\">Ссылки</h2>\n<div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px\">\n<label style=\"display: flex; flex-direction: column; gap: 6px; font-size: 14px; color: #B9AED6\">YouTube<input id=\"lnYoutube\" type=\"url\" value=\"{{f.youtube}}\" onInput=\"{{onYoutube}}\" placeholder=\"https://youtube.com/@...\" style=\"padding: 12px 14px; min-height: 44px; box-sizing: border-box; border-radius: 10px; border: 1px solid #2E2250; background: #0E0A1A; color: #FFFFFF; font: inherit\"></label>\n<label style=\"display: flex; flex-direction: column; gap: 6px; font-size: 14px; color: #B9AED6\">Twitch<input id=\"lnTwitch\" type=\"url\" value=\"{{f.twitch}}\" onInput=\"{{onTwitch}}\" placeholder=\"https://twitch.tv/...\" style=\"padding: 12px 14px; min-height: 44px; box-sizing: border-box; border-radius: 10px; border: 1px solid #2E2250; background: #0E0A1A; color: #FFFFFF; font: inherit\"></label>\n<label style=\"display: flex; flex-direction: column; gap: 6px; font-size: 14px; color: #B9AED6\">TikTok<input id=\"lnTiktok\" type=\"url\" value=\"{{f.tiktok}}\" onInput=\"{{onTiktok}}\" placeholder=\"https://tiktok.com/@...\" style=\"padding: 12px 14px; min-height: 44px; box-sizing: border-box; border-radius: 10px; border: 1px solid #2E2250; background: #0E0A1A; color: #FFFFFF; font: inherit\"></label>\n</div>\n</div>\n\n<div style=\"background: #170F2B; border: 1px solid #2E2250; border-radius: 18px; padding: 22px; display: flex; flex-direction: column; gap: 12px\">\n<h2 style=\"margin: 0; font-size: 18px; color: #FFFFFF\">Приватность</h2>\n<label style=\"display: flex; gap: 10px; align-items: center; color: #E2DAF5\"><input id=\"showDiscord\" type=\"checkbox\" checked=\"{{f.showDiscord}}\" onChange=\"{{onShowDiscord}}\" style=\"width: 18px; height: 18px; accent-color: #8B3DFF\">Показывать мой Discord в профиле</label>\n</div>\n\n<template data-sc=\"if\" value=\"{{error}}\"><div role=\"alert\" style=\"padding: 12px 16px; border-radius: 10px; background: #2A1430; color: #FFD6E2; font-weight: 600\">{{error}}</div></template>\n<div style=\"display: flex; flex-wrap: wrap; gap: 10px\">\n<button type=\"button\" onClick=\"{{save}}\" style=\"padding: 14px 24px; min-height: 48px; border-radius: 12px; border: none; background: #8B3DFF; color: #FFFFFF; font: inherit; font-weight: 800; cursor: pointer\">{{saveLabel}}</button>\n<button type=\"button\" onClick=\"{{toggleEdit}}\" style=\"padding: 14px 24px; min-height: 48px; border-radius: 12px; border: 1px solid #2E2250; background: #1F1638; color: #EFE8FF; font: inherit; font-weight: 700; cursor: pointer\">Отмена</button>\n</div>\n</div>\n</template>\n</section>\n</template>\n\n<footer style=\"background: #08060F; border-top: 1px solid #241A40\">\n<div style=\"max-width: 1240px; margin: 0 auto; padding: 32px 24px; display: flex; flex-wrap: wrap; gap: 16px; justify-content: space-between; color: #B9AED6; font-size: 14px\">\n<span>© 2026 Komori · mc.komori.fun · Не связан с Mojang и Microsoft.</span>\n<span style=\"display: flex; gap: 20px; flex-wrap: wrap\"><a href=\"/rules\">Правила</a><a href=\"/wiki\">Вики</a><a href=\"/map\">Карта</a><a href=\"{{K.launcher}}\">Лаунчер</a><a href=\"{{K.discord}}\" target=\"_blank\" rel=\"noopener\">Discord</a></span>\n</div>\n</footer>\n</div>\n</template><x-dc></x-dc>\n<script type=\"text/x-dc\" data-dc-script>\nclass Component extends DCLogic {\nconstructor(props) {\nsuper(props);\nthis.state = { p: null, missing: false, editing: false, f: null, copied: false, saving: false, error: '' };\n}\nmounted() {\nvar self = this, k = window.KOMORI || {};\nvar m = location.pathname.match(/^\\/u\\/(\\d{5,25})$/);\nvar url = m ? '/api/user/' + m[1] : '/api/me';\nif (!m && !k.me) { this.setState({ missing: true }); return; }\nfetch(url).then(function (r) { return r.ok ? r.json() : null; }).then(function (p) {\nif (!p) self.setState({ missing: true }); else self.setState({ p: p });\n}).catch(function () { self.setState({ missing: true }); });\n}\nrenderVals() {\nvar self = this, s = this.state, p = s.p, k = window.KOMORI || {};\nvar own = !!(p && k.me && k.me.id === p.id);\nvar f = s.f || (p ? { status: p.status || '', bio: p.bio || '', accent: p.accent, youtube: (p.links || {}).youtube || '', twitch: (p.links || {}).twitch || '', tiktok: (p.links || {}).tiktok || '', showDiscord: !!p.showDiscord } : {});\nvar accent = (s.editing ? f.accent : p && p.accent) || '#B57BFF';\nvar COLORS = [['#B57BFF', 'Фиолетовый'], ['#FF7EDB', 'Розовый'], ['#6FA8FF', 'Синий'], ['#5FE0C8', 'Бирюзовый'], ['#7BD88F', 'Зелёный'], ['#FFC857', 'Золотой'], ['#FF8A6B', 'Коралловый']];\nfunction setF(key) { return function (e) { var n = Object.assign({}, f); n[key] = e.target.type === 'checkbox' ? e.target.checked : e.target.value; self.setState({ f: n }); }; }\nvar links = p ? p.links || {} : {};\nvar shown = s.editing ? f : (p || {});\nreturn {\nloading: !p && !s.missing,\nnotFound: s.missing,\nnotFoundTitle: k.me || /^\\/u\\//.test(location.pathname) ? 'Профиль не найден' : 'Войди, чтобы открыть профиль',\nnotFoundText: k.me || /^\\/u\\//.test(location.pathname) ? 'Такого игрока нет или он ещё не заходил на сайт.' : 'Профиль создаётся автоматически при первом входе через Discord.',\nready: !!p,\nown: own,\np: p || {},\naccent: accent,\nbadges: (p && p.badges) || [],\nstatusShown: shown.status || 'Без статуса',\nbioShown: (p && p.bio) || 'Игрок пока ничего не рассказал о себе.',\nlinkList: [['youtube', 'YouTube'], ['twitch', 'Twitch'], ['tiktok', 'TikTok']].filter(function (x) { return links[x[0]]; }).map(function (x) { return { url: links[x[0]], label: x[1] }; }),\nviewing: !s.editing, editing: s.editing && own,\neditLabel: s.editing ? 'Готово' : 'Редактировать профиль',\ntoggleEdit: function () { self.setState({ editing: !s.editing, f: null, error: '' }); },\nshareLabel: s.copied ? 'Ссылка скопирована' : 'Поделиться',\nshare: function () {\ntry { navigator.clipboard.writeText(location.origin + '/u/' + p.id); } catch (e) {}\nself.setState({ copied: true }); setTimeout(function () { self.setState({ copied: false }); }, 1500);\n},\nf: f,\nstatusCount: (f.status || '').length, bioCount: (f.bio || '').length,\nonStatus: setF('status'), onBio: setF('bio'), onYoutube: setF('youtube'), onTwitch: setF('twitch'), onTiktok: setF('tiktok'), onShowDiscord: setF('showDiscord'),\ncolors: COLORS.map(function (c) {\nvar on = c[0] === f.accent;\nreturn { hex: c[0], name: c[1], on: on ? 'true' : 'false', ring: on ? '#FFFFFF' : '#2E2250', pick: function () { self.setState({ f: Object.assign({}, f, { accent: c[0] }) }); } };\n}),\nerror: s.error,\nsaveLabel: s.saving ? 'Сохраняю…' : 'Сохранить',\nsave: function () {\nif (s.saving) return;\nself.setState({ saving: true, error: '' });\nfetch('/api/me', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({\nstatus: f.status, bio: f.bio, accent: f.accent, showDiscord: f.showDiscord,\nlinks: { youtube: f.youtube, twitch: f.twitch, tiktok: f.tiktok } }) })\n.then(function (r) { return r.json().then(function (d) { return { ok: r.ok, d: d }; }); })\n.then(function (res) {\nif (!res.ok) { self.setState({ saving: false, error: res.d.error || 'Не удалось сохранить' }); return; }\nself.setState({ saving: false, editing: false, f: null, p: res.d });\n}).catch(function () { self.setState({ saving: false, error: 'Нет связи с сайтом, попробуй ещё раз' }); });\n}\n};\n}\n}\n</script>\n</body>\n</html>\n","rules":"<!doctype html>\n<html lang=\"ru\">\n<head>\n<meta charset=\"utf-8\">\n<title>Правила — Komori</title>\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<link rel=\"icon\" href=\"/assets/favicon.png\">\n<meta name=\"theme-color\" content=\"#0E0A1A\">\n<style>x-dc{display:none}</style>\n<!--BOOT-->\n<script src=\"/komori-dc.js\" defer></script>\n</head>\n<body>\n<template id=\"komori-tpl\">\n<helmet>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Unbounded:wght@500;700;800&amp;family=Manrope:wght@400;500;600;700&amp;display=swap\">\n<style>\nbody{margin:0;background:#0E0A1A}\na{color:#D9B8FF}a:hover{color:#F3E6FF}\n</style>\n</helmet>\n<div style=\"min-height: 100vh; background: #0E0A1A; color: #EFE8FF; font-family: 'Manrope', system-ui, sans-serif; font-size: 16px; line-height: 1.6\">\n\n<header style=\"position: sticky; top: 0; z-index: 10; background: #08060F; border-bottom: 1px solid #241A40\">\n<div style=\"max-width: 1240px; margin: 0 auto; padding: 12px 24px; display: flex; flex-wrap: wrap; align-items: center; gap: 12px 28px\">\n<a href=\"/\" style=\"display: flex; align-items: center; gap: 12px; text-decoration: none; color: #F3E6FF\">\n<img src=\"/assets/logo.png\" alt=\"Логотип Komori\" style=\"height: 44px; width: 44px; display: block\">\n<span style=\"font-family: 'Unbounded', sans-serif; font-weight: 800; font-size: 22px; letter-spacing: 0.04em\">KOMORI</span>\n</a>\n<nav aria-label=\"Основное меню\" style=\"display: flex; flex-wrap: wrap; gap: 4px; flex: 1 1 420px\">\n<template data-sc=\"for\" list=\"{{K.nav}}\" as=\"n\">\n<a href=\"{{n.href}}\" aria-current=\"{{n.current}}\" style=\"padding: 10px 14px; border-radius: 8px; text-decoration: none; color: {{n.color}}; background: {{n.bg}}; font-weight: 700\">{{n.label}}</a>\n</template>\n</nav>\n<div style=\"display: flex; flex-wrap: wrap; gap: 10px; align-items: center\">\n<template data-sc=\"if\" value=\"{{K.loggedIn}}\">\n<a href=\"/profile\" style=\"display: flex; align-items: center; gap: 10px; padding: 6px 14px 6px 6px; min-height: 44px; box-sizing: border-box; border-radius: 10px; border: 1px solid #2E2250; background: #170F2B; color: #EFE8FF; text-decoration: none; font-weight: 700\">\n<img src=\"{{K.avatar}}\" alt=\"\" width=\"32\" height=\"32\" style=\"width: 32px; height: 32px; border-radius: 50%; display: block; background: #2A1E4A\">\n{{K.name}}\n</a>\n<button type=\"button\" onClick=\"{{K.logout}}\" style=\"padding: 11px 14px; min-height: 44px; border-radius: 10px; border: 1px solid #2E2250; background: transparent; color: #FF9FB8; font: inherit; font-weight: 700; cursor: pointer\">Выйти</button>\n</template>\n<template data-sc=\"if\" value=\"{{K.loggedOut}}\">\n<a href=\"{{K.loginUrl}}\" style=\"display: flex; align-items: center; gap: 8px; padding: 11px 18px; min-height: 44px; box-sizing: border-box; border-radius: 10px; background: #5865F2; color: #FFFFFF; text-decoration: none; font-weight: 700\">\n<svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4\"></path><path d=\"M10 17l5-5-5-5\"></path><path d=\"M15 12H3\"></path></svg>\nВойти через Discord\n</a>\n</template>\n</div>\n</div>\n<template data-sc=\"if\" value=\"{{K.flash}}\">\n<div role=\"status\" style=\"max-width: 1240px; margin: 0 auto 12px; padding: 12px 24px\">\n<div style=\"padding: 12px 16px; border-radius: 10px; background: #3A2A10; color: #FFD48A; font-weight: 600\">{{K.flash}} <template data-sc=\"if\" value=\"{{K.flashJoin}}\"><a href=\"{{K.discord}}\" target=\"_blank\" rel=\"noopener\" style=\"color: #FFFFFF\">Зайти на сервер Discord</a></template></div>\n</div>\n</template>\n</header>\n\n<section style=\"max-width: 1240px; margin: 0 auto; padding: 56px 24px 32px; display: flex; flex-direction: column; gap: 24px\">\n<h1 style=\"margin: 0; font-family: 'Unbounded', sans-serif; font-weight: 800; font-size: clamp(32px, 4.5vw, 52px); color: #FFFFFF\">Правила проекта</h1>\n<p style=\"margin: 0; color: #C7BBE6; max-width: 720px; font-size: 18px\">Действуют на Minecraft-сервере, в Discord и на всех официальных площадках Komori. Незнание правил не освобождает от ответственности.</p>\n<div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 14px\">\n<div style=\"background: #170F2B; border: 1px solid #2E2250; border-radius: 14px; padding: 18px; display: flex; gap: 12px; align-items: flex-start\">\n<svg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#B57BFF\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 3l8 4v5c0 5-3.5 8-8 9-4.5-1-8-4-8-9V7z\"></path><path d=\"M9 12l2 2 4-4\"></path></svg>\n<span><b style=\"color: #FFFFFF\">Без читов</b><br><span style=\"color: #C7BBE6; font-size: 15px\">и модов с нечестным преимуществом</span></span>\n</div>\n<div style=\"background: #170F2B; border: 1px solid #2E2250; border-radius: 14px; padding: 18px; display: flex; gap: 12px; align-items: flex-start\">\n<svg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#B57BFF\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 21h18M5 21V9l7-5 7 5v12\"></path><path d=\"M10 21v-6h4v6\"></path></svg>\n<span><b style=\"color: #FFFFFF\">Без гриферства</b><br><span style=\"color: #C7BBE6; font-size: 15px\">чужое не ломать и не забирать</span></span>\n</div>\n<div style=\"background: #170F2B; border: 1px solid #2E2250; border-radius: 14px; padding: 18px; display: flex; gap: 12px; align-items: flex-start\">\n<svg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#B57BFF\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M20 12a8 8 0 0 1-11.6 7.1L4 20l1-4.2A8 8 0 1 1 20 12z\"></path></svg>\n<span><b style=\"color: #FFFFFF\">Уважай других</b><br><span style=\"color: #C7BBE6; font-size: 15px\">без оскорблений, травли и провокаций</span></span>\n</div>\n<div style=\"background: #170F2B; border: 1px solid #2E2250; border-radius: 14px; padding: 18px; display: flex; gap: 12px; align-items: flex-start\">\n<svg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#B57BFF\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M5.6 5.6l12.8 12.8\"></path></svg>\n<span><b style=\"color: #FFFFFF\">Без рекламы</b><br><span style=\"color: #C7BBE6; font-size: 15px\">других серверов и сообществ</span></span>\n</div>\n</div>\n</section>\n\n<section style=\"max-width: 1240px; margin: 0 auto; padding: 0 24px 80px; display: flex; flex-wrap: wrap; gap: 28px; align-items: flex-start\">\n\n<nav aria-label=\"Разделы правил\" style=\"flex: 1 1 240px; background: #170F2B; border: 1px solid #2E2250; border-radius: 18px; padding: 10px; display: flex; flex-direction: column; gap: 2px\">\n<template data-sc=\"for\" list=\"{{sections}}\" as=\"s\" hint-placeholder-count=\"5\">\n<a href=\"#{{s.id}}\" style=\"display: flex; gap: 10px; align-items: center; padding: 12px 12px; border-radius: 10px; text-decoration: none; color: #EFE8FF; font-weight: 600\">\n<span style=\"min-width: 28px; height: 28px; border-radius: 8px; background: #2A1E4A; color: #D9B8FF; display: flex; align-items: center; justify-content: center; font-family: 'Unbounded', sans-serif; font-size: 13px; font-weight: 700\">{{s.num}}</span>\n{{s.title}}\n</a>\n</template>\n</nav>\n\n<div style=\"flex: 999 1 560px; min-width: 0; display: flex; flex-direction: column; gap: 24px\">\n<template data-sc=\"for\" list=\"{{sections}}\" as=\"s\" hint-placeholder-count=\"5\">\n<article id=\"{{s.id}}\" style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 20px; padding: 28px; display: flex; flex-direction: column; gap: 20px\">\n<div style=\"display: flex; align-items: center; gap: 14px\">\n<span style=\"width: 52px; height: 52px; border-radius: 14px; background: #8B3DFF; color: #FFFFFF; display: flex; align-items: center; justify-content: center; font-family: 'Unbounded', sans-serif; font-size: 22px; font-weight: 800\">{{s.num}}</span>\n<h2 style=\"margin: 0; font-family: 'Unbounded', sans-serif; font-size: 24px; color: #FFFFFF\">{{s.title}}</h2>\n</div>\n<template data-sc=\"if\" value=\"{{s.hasNote}}\" hint-placeholder-val=\"{{ false }}\">\n<p style=\"margin: 0; padding: 14px 16px; border-radius: 12px; background: #1F1638; color: #D9CCF5\">{{s.note}}</p>\n</template>\n<template data-sc=\"for\" list=\"{{s.groups}}\" as=\"g\" hint-placeholder-count=\"1\">\n<div style=\"display: flex; flex-direction: column; gap: 10px\">\n<template data-sc=\"if\" value=\"{{g.hasTitle}}\" hint-placeholder-val=\"{{ false }}\">\n<h3 style=\"margin: 8px 0 0; font-size: 18px; color: #E6D2FF\">{{g.title}}</h3>\n</template>\n<template data-sc=\"for\" list=\"{{g.items}}\" as=\"it\" hint-placeholder-count=\"3\">\n<div style=\"display: flex; gap: 14px; align-items: flex-start; padding: 10px 0; border-bottom: 1px solid #221839\">\n<span style=\"flex: 0 0 auto; min-width: 52px; padding: 2px 8px; box-sizing: border-box; border-radius: 8px; background: #1F1638; color: #C99BFF; font-weight: 700; font-size: 14px; text-align: center\">{{it.n}}</span>\n<span style=\"color: #E2DAF5\">{{it.t}}</span>\n</div>\n</template>\n<template data-sc=\"if\" value=\"{{g.hasList}}\" hint-placeholder-val=\"{{ false }}\">\n<div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 10px\">\n<template data-sc=\"for\" list=\"{{g.list}}\" as=\"li\" hint-placeholder-count=\"4\">\n<div style=\"background: #1A1230; border: 1px solid #2E2250; border-radius: 12px; padding: 14px\">\n<div style=\"font-weight: 800; color: #FF9FD8\">{{li.name}}</div>\n<div style=\"color: #C7BBE6; font-size: 15px\">{{li.t}}</div>\n</div>\n</template>\n</div>\n</template>\n<template data-sc=\"for\" list=\"{{g.after}}\" as=\"a\" hint-placeholder-count=\"0\">\n<p style=\"margin: 0; color: #C7BBE6; font-size: 15px\">{{a.t}}</p>\n</template>\n</div>\n</template>\n</article>\n</template>\n</div>\n</section>\n\n<footer style=\"background: #08060F; border-top: 1px solid #241A40\">\n<div style=\"max-width: 1240px; margin: 0 auto; padding: 32px 24px; display: flex; flex-wrap: wrap; gap: 16px; justify-content: space-between; color: #B9AED6; font-size: 14px\">\n<span>© 2026 Komori · mc.komori.fun · Не связан с Mojang и Microsoft.</span>\n<span style=\"display: flex; gap: 20px; flex-wrap: wrap\"><a href=\"/rules\">Правила</a><a href=\"/wiki\">Вики</a><a href=\"/map\">Карта</a><a href=\"{{K.launcher}}\">Лаунчер</a><a href=\"{{K.discord}}\" target=\"_blank\" rel=\"noopener\">Discord</a></span>\n</div>\n</footer>\n\n</div>\n</template><x-dc></x-dc>\n<script type=\"text/x-dc\" data-dc-script>\nclass Component extends DCLogic {\nrenderVals() {\nfunction g(title, pairs, extra) {\nextra = extra || {};\nreturn {\ntitle: title || '', hasTitle: !!title,\nitems: pairs.map(function (p) { return { n: p[0], t: p[1] }; }),\nhasList: !!extra.list, list: extra.list || [],\nafter: (extra.after || []).map(function (t) { return { t: t }; })\n};\n}\nvar sections = [\n{ id: 's1', num: '1', title: 'Общие положения', groups: [g('', [\n['1.1', 'Правила распространяются на все площадки проекта Komori: Minecraft-сервер, Discord-сервер и другие официальные ресурсы.'],\n['1.2', 'Правила также действуют за пределами официальных площадок, если общение связано с Komori и направлено на обман, травлю или причинение вреда участникам.'],\n['1.3', 'Каждый участник обязан соблюдать правила и уважать других игроков. Незнание правил не освобождает от ответственности.'],\n['1.4', 'Администрация рассматривает нарушения с учётом контекста, тяжести, последствий и истории нарушений участника.'],\n['1.5', 'Администрация сама выбирает меру наказания в пределах своих полномочий. За повторные или особо серьёзные нарушения наказание может быть строже.'],\n['1.6', 'Запрещено намеренно провоцировать конфликты, мешать общению других и создавать враждебную атмосферу.'],\n['1.7', 'Запрещены оскорбления, унижение, травля и целенаправленные провокации в отношении участников.'],\n['1.8', 'Запрещены расизм, дискриминация, разжигание ненависти и призывы к вражде по признаку принадлежности к какой-либо группе.'],\n['1.9', 'Запрещены угрозы реальной расправой, публикация чужих персональных данных без разрешения и другие действия, угрожающие безопасности участников.'],\n['1.10', 'Запрещены политические и религиозные споры, провоцирующие конфликты.'],\n['1.11', 'Запрещены флуд, спам, злоупотребление упоминаниями, чрезмерный капс и символы, если это мешает общению.'],\n['1.12', 'Запрещена публикация порнографии, материалов для взрослых, шок-контента и сцен жестокости.'],\n['1.13', 'Запрещена реклама других Minecraft-серверов, Discord-сообществ, каналов, сайтов и соцсетей без разрешения администрации.'],\n['1.14', 'Запрещено выдавать себя за администратора, модератора или другого участника ради обмана или преимущества.'],\n['1.15', 'Участник отвечает за все действия со своего аккаунта, в том числе если передал его другому человеку.'],\n['1.16', 'Запрещено обходить наказания с помощью других аккаунтов, передавать аккаунты для обхода наказания и помогать в этом другим.'],\n['1.17', 'На внешних площадках запрещены мошенничество, фишинг, обман участников и организованная травля, связанные с Komori.'],\n['1.18', 'Запрещено создавать фальшивые сообщества и аккаунты от имени Komori и распространять подозрительные ссылки или вредоносные файлы под видом официальных материалов.']\n])] },\n{ id: 's2', num: '2', title: 'Discord', note: 'Общие правила из раздела 1 (флуд, реклама, контент 18+, обход блокировок, выдача себя за администрацию) действуют и в Discord.', groups: [g('', [\n['2.1', 'Соблюдай тематику каналов и не пиши сообщения, не относящиеся к назначению канала.'],\n['2.2', 'Запрещено злоупотреблять упоминаниями участников и ролей, в том числе делать массовые упоминания без необходимости.'],\n['2.3', 'В голосовых каналах запрещены микрофонный спам, крики, громкие звуки и злоупотребление звуковой панелью, если это мешает другим.'],\n['2.4', 'Запрещено рассылать участникам рекламу и спам в личных сообщениях, используя связь с Komori.'],\n['2.5', 'Запрещено распространять вредоносные файлы, фишинговые ссылки и материалы для кражи аккаунтов или данных.'],\n['2.6', 'Запрещено публиковать чужие личные переписки и персональные данные без разрешения. Исключение — передача материалов администрации для рассмотрения жалобы.'],\n['2.7', 'Запрещено намеренно срывать работу Discord-сервера, мешать модерации и рассмотрению жалоб.']\n])] },\n{ id: 's3', num: '3', title: 'Minecraft-сервер', groups: [\ng('3.1. Читы и модификации', [\n['3.1.1', 'Запрещены читы, чит-клиенты и модификации, дающие нечестное преимущество над другими игроками. В частности:']\n], { list: [\n{ name: 'X-Ray', t: 'поиск руд и скрытых ресурсов сквозь блоки' },\n{ name: 'KillAura, AimAssist, Aimbot', t: 'автоматизация или облегчение наведения и атак' },\n{ name: 'Reach', t: 'увеличенная дальность атаки или взаимодействия' },\n{ name: 'Fly, SpeedHack, NoClip', t: 'полёт, ускорение, прохождение сквозь блоки' },\n{ name: 'Freecam', t: 'осмотр окружения сверх обычных возможностей, если даёт преимущество' },\n{ name: 'ESP, PlayerESP', t: 'игроки, мобы и объекты сквозь стены' },\n{ name: 'AutoClicker, TriggerBot', t: 'автоматические клики и атаки при наведении' },\n{ name: 'Прочее', t: 'автопоиск целей, уклонение от атак, обход ограничений и другие похожие инструменты' }\n], after: [\n'Чит-клиенты (например, Meteor Client, LiquidBounce, Wurst, Aristois, Impact) запрещены, если их функции дают нечестное преимущество.',\n'Разрешённость мода определяется его функциями, а не названием. Косметические моды и моды интерфейса без игрового преимущества разрешены.'\n] }),\ng('3.2. Ошибки игры', [\n['3.2.1', 'Запрещено использовать баги и уязвимости игры или сервера для нечестного преимущества.'],\n['3.2.2', 'Запрещены дюпы и другие способы размножения предметов, а также передача полученных так ресурсов.'],\n['3.2.3', 'О критических ошибках, влияющих на экономику, безопасность или стабильность сервера, нужно сообщать администрации.']\n]),\ng('3.3. Имущество и территории', [\n['3.3.1', 'Запрещено гриферство: разрушение чужих построек и механизмов, порча имущества и другой намеренный ущерб игрокам.'],\n['3.3.2', 'Запрещено забирать чужие вещи и ресурсы без разрешения владельца.'],\n['3.3.3', 'Запрещено захватывать чужие территории или блокировать владельцу доступ к его постройкам.'],\n['3.3.4', 'Запрещено строить вплотную к чужим постройкам, чтобы мешать владельцу или портить вид территории.'],\n['3.3.5', 'Запрещено блокировать чужие порталы, важные проходы и пути доступа.']\n]),\ng('3.4. PvP и ловушки', [\n['3.4.1', 'PvP и ловушки сами по себе разрешены.'],\n['3.4.2', 'Запрещено убивать игроков в PvP или заманивать их в ловушки ради того, чтобы забрать их вещи и ресурсы.']\n]),\ng('3.5. Нагрузка на сервер', [\n['3.5.1', 'Запрещено строить лаг-машины и намеренно перегружать сервер.'],\n['3.5.2', 'Запрещено злоупотреблять игровыми механиками для нечестного преимущества или обхода ограничений.'],\n['3.5.3', 'Запрещено обходить AFK-систему, если это даёт преимущество или позволяет обойти ограничения сервера.']\n]),\ng('3.6. Дополнительные аккаунты', [\n['3.6.1', 'Запрещено использовать дополнительные аккаунты для обхода ограничений и наказаний.'],\n['3.6.2', 'Запрещено использовать дополнительные аккаунты для получения преимуществ, недоступных при обычной игре.']\n]),\ng('3.7. Экономика', [\n['3.7.1', 'Запрещено покупать и продавать игровые ресурсы и ценности за реальные деньги вне официального доната проекта.'],\n['3.7.2', 'Запрещено получать экономическое преимущество с помощью багов, читов и других запрещённых методов.']\n]),\ng('3.8. Ники и внешний вид', [\n['3.8.1', 'Запрещены неприемлемые ники, названия предметов и скины с оскорблениями, дискриминацией или неприемлемым контентом.'],\n['3.8.2', 'Запрещено оформление, с помощью которого игрок выдаёт себя за администрацию или другого игрока.']\n]),\ng('3.9. Мероприятия и администрация', [\n['3.9.1', 'Запрещено срывать серверные мероприятия и мешать другим в них участвовать.'],\n['3.9.2', 'Игроки обязаны выполнять требования администрации, связанные с соблюдением правил и работой сервера.'],\n['3.9.3', 'Запрещено мешать работе администрации, проверке нарушений или скрывать нарушения.']\n])\n] },\n{ id: 's4', num: '4', title: 'Администрация и жалобы', groups: [g('', [\n['4.1', 'Администрация вправе рассматривать жалобы, запрашивать доказательства, проверять игровые логи и удалять контент, нарушающий правила.'],\n['4.2', 'При решении учитываются доказательства, контекст, тяжесть нарушения, последствия и повторяемость.'],\n['4.3', 'Возможные наказания: предупреждение, временное ограничение возможностей, временная или постоянная блокировка.'],\n['4.4', 'Повторные нарушения могут повлечь более строгое наказание.'],\n['4.5', 'Администрации запрещено злоупотреблять полномочиями, использовать их в личных целях и применять правила избирательно.'],\n['4.6', 'Участник может подать апелляцию через канал #поддержка в Discord.'],\n['4.7', 'Апелляция не гарантирует отмену наказания: решение принимается после рассмотрения обстоятельств и доказательств.'],\n['4.8', 'Запрещены ложные жалобы, подделка доказательств и искажение обстоятельств ради наказания другого участника.']\n])] },\n{ id: 's5', num: '5', title: 'Заключительные положения', groups: [g('', [\n['5.1', 'Правила нужны для комфортной, безопасной и честной игры на проекте Komori.'],\n['5.2', 'Каждая ситуация рассматривается индивидуально, с учётом обстоятельств и последствий.'],\n['5.3', 'Если ситуация не описана в правилах, администрация решает её исходя из общих положений и цели нормальной работы проекта.'],\n['5.4', 'Администрация может обновлять правила. Следи за официальными объявлениями.'],\n['5.5', 'Продолжая пользоваться площадками Komori, участник соглашается соблюдать действующие правила.']\n])] }\n];\nreturn {\nsections: sections.map(function (s) {\nreturn { id: s.id, num: s.num, title: s.title, hasNote: !!s.note, note: s.note || '', groups: s.groups };\n})\n};\n}\n}\n</script>\n</body>\n</html>\n","wiki":"<!doctype html>\n<html lang=\"ru\">\n<head>\n<meta charset=\"utf-8\">\n<title>Вики — Komori</title>\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<link rel=\"icon\" href=\"/assets/favicon.png\">\n<meta name=\"theme-color\" content=\"#0E0A1A\">\n<style>x-dc{display:none}</style>\n<!--BOOT-->\n<script src=\"/komori-dc.js\" defer></script>\n</head>\n<body>\n<template id=\"komori-tpl\">\n<helmet>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Unbounded:wght@500;700;800&amp;family=Manrope:wght@400;500;600;700&amp;display=swap\">\n<style>\nbody{margin:0;background:#0E0A1A}\na{color:#D9B8FF}a:hover{color:#F3E6FF}\n</style>\n</helmet>\n<div style=\"min-height: 100vh; background: #0E0A1A; color: #EFE8FF; font-family: 'Manrope', system-ui, sans-serif; font-size: 16px; line-height: 1.6\">\n\n<header style=\"position: sticky; top: 0; z-index: 10; background: #08060F; border-bottom: 1px solid #241A40\">\n<div style=\"max-width: 1240px; margin: 0 auto; padding: 12px 24px; display: flex; flex-wrap: wrap; align-items: center; gap: 12px 28px\">\n<a href=\"/\" style=\"display: flex; align-items: center; gap: 12px; text-decoration: none; color: #F3E6FF\">\n<img src=\"/assets/logo.png\" alt=\"Логотип Komori\" style=\"height: 44px; width: 44px; display: block\">\n<span style=\"font-family: 'Unbounded', sans-serif; font-weight: 800; font-size: 22px; letter-spacing: 0.04em\">KOMORI</span>\n</a>\n<nav aria-label=\"Основное меню\" style=\"display: flex; flex-wrap: wrap; gap: 4px; flex: 1 1 420px\">\n<template data-sc=\"for\" list=\"{{K.nav}}\" as=\"n\">\n<a href=\"{{n.href}}\" aria-current=\"{{n.current}}\" style=\"padding: 10px 14px; border-radius: 8px; text-decoration: none; color: {{n.color}}; background: {{n.bg}}; font-weight: 700\">{{n.label}}</a>\n</template>\n</nav>\n<div style=\"display: flex; flex-wrap: wrap; gap: 10px; align-items: center\">\n<template data-sc=\"if\" value=\"{{K.loggedIn}}\">\n<a href=\"/profile\" style=\"display: flex; align-items: center; gap: 10px; padding: 6px 14px 6px 6px; min-height: 44px; box-sizing: border-box; border-radius: 10px; border: 1px solid #2E2250; background: #170F2B; color: #EFE8FF; text-decoration: none; font-weight: 700\">\n<img src=\"{{K.avatar}}\" alt=\"\" width=\"32\" height=\"32\" style=\"width: 32px; height: 32px; border-radius: 50%; display: block; background: #2A1E4A\">\n{{K.name}}\n</a>\n<button type=\"button\" onClick=\"{{K.logout}}\" style=\"padding: 11px 14px; min-height: 44px; border-radius: 10px; border: 1px solid #2E2250; background: transparent; color: #FF9FB8; font: inherit; font-weight: 700; cursor: pointer\">Выйти</button>\n</template>\n<template data-sc=\"if\" value=\"{{K.loggedOut}}\">\n<a href=\"{{K.loginUrl}}\" style=\"display: flex; align-items: center; gap: 8px; padding: 11px 18px; min-height: 44px; box-sizing: border-box; border-radius: 10px; background: #5865F2; color: #FFFFFF; text-decoration: none; font-weight: 700\">\n<svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4\"></path><path d=\"M10 17l5-5-5-5\"></path><path d=\"M15 12H3\"></path></svg>\nВойти через Discord\n</a>\n</template>\n</div>\n</div>\n<template data-sc=\"if\" value=\"{{K.flash}}\">\n<div role=\"status\" style=\"max-width: 1240px; margin: 0 auto 12px; padding: 12px 24px\">\n<div style=\"padding: 12px 16px; border-radius: 10px; background: #3A2A10; color: #FFD48A; font-weight: 600\">{{K.flash}} <template data-sc=\"if\" value=\"{{K.flashJoin}}\"><a href=\"{{K.discord}}\" target=\"_blank\" rel=\"noopener\" style=\"color: #FFFFFF\">Зайти на сервер Discord</a></template></div>\n</div>\n</template>\n</header>\n\n<section style=\"max-width: 1240px; margin: 0 auto; padding: 48px 24px 28px; display: flex; flex-direction: column; gap: 18px\">\n<h1 style=\"margin: 0; font-family: 'Unbounded', sans-serif; font-weight: 800; font-size: clamp(32px, 4.5vw, 52px); color: #FFFFFF\">Вики Komori</h1>\n<p style=\"margin: 0; color: #C7BBE6; max-width: 680px; font-size: 18px\">Рыбалка, 132 рыбы, снасти, 73 зачарования, магазин игроков, награды за головы, топы и команды.</p>\n<div style=\"display: flex; align-items: center; gap: 10px; max-width: 560px; padding: 0 14px; border-radius: 12px; border: 1px solid #2E2250; background: #170F2B\">\n<svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#B9AED6\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\"></circle><path d=\"M20 20l-3.5-3.5\"></path></svg>\n<label for=\"wikiSearch\" style=\"position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0)\">Поиск по вики</label>\n<input id=\"wikiSearch\" type=\"search\" placeholder=\"Поиск: команда, рыба, зачарование…\" style=\"flex: 1; min-height: 48px; border: none; background: transparent; color: #FFFFFF; font: inherit; outline: none\">\n</div>\n</section>\n\n<section style=\"max-width: 1240px; margin: 0 auto; padding: 0 24px 80px; display: flex; flex-wrap: wrap; gap: 28px; align-items: flex-start\">\n\n<nav aria-label=\"Разделы вики\" style=\"flex: 1 1 240px; background: #170F2B; border: 1px solid #2E2250; border-radius: 18px; padding: 8px; display: flex; flex-direction: column; gap: 4px\">\n<template data-sc=\"for\" list=\"{{tabs}}\" as=\"t\" hint-placeholder-count=\"8\">\n<button type=\"button\" onClick=\"{{t.pick}}\" aria-current=\"{{t.current}}\" style=\"display: flex; flex-direction: column; text-align: left; padding: 12px 14px; min-height: 44px; border-radius: 10px; border: none; background: {{t.bg}}; color: {{t.color}}; font: inherit; cursor: pointer\">\n<span style=\"font-weight: 700\">{{t.label}}</span>\n<span style=\"font-size: 13px; color: {{t.sub}}\">{{t.hint}}</span>\n</button>\n</template>\n</nav>\n\n<div style=\"flex: 999 1 560px; min-width: 0; display: flex; flex-direction: column; gap: 22px\">\n\n<template data-sc=\"if\" value=\"{{showFish}}\" hint-placeholder-val=\"{{ true }}\">\n<div style=\"display: flex; flex-direction: column; gap: 22px\">\n<img src=\"/assets/hero.jpg\" alt=\"Fishing Update\" style=\"width: 100%; aspect-ratio: 16 / 7; object-fit: cover; display: block; border-radius: 20px; border: 1px solid #2E2250\">\n<h2 style=\"margin: 0; font-family: 'Unbounded', sans-serif; font-size: 30px; color: #FFFFFF\">Рыбалка</h2>\n<p style=\"margin: 0; color: #C7BBE6\">Своя система рыбалки Komori. При поклёвке на экране запускается мини-игра, улов зависит от биома, а за пойманную рыбу ты получаешь очки рыбака и рыбацкие монеты с продажи.</p>\n\n<div style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 18px; padding: 24px; display: flex; flex-direction: column; gap: 14px\">\n<h3 style=\"margin: 0; font-size: 20px; color: #FFFFFF\">Мини-игра</h3>\n<div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 12px\">\n<div style=\"background: #1F1638; border-radius: 14px; padding: 16px\">\n<div style=\"font-family: 'Unbounded', sans-serif; font-size: 22px; font-weight: 800; color: #B57BFF\">5 шкал</div>\n<div style=\"color: #C7BBE6; font-size: 15px\">Ползунок бегает вверх-вниз. Жми <b style=\"color: #FFFFFF\">F</b>, когда он в зелёной зоне, — переходишь к следующей шкале.</div>\n</div>\n<div style=\"background: #1F1638; border-radius: 14px; padding: 16px\">\n<div style=\"font-family: 'Unbounded', sans-serif; font-size: 22px; font-weight: 800; color: #B57BFF\">3 жизни</div>\n<div style=\"color: #C7BBE6; font-size: 15px\">Промах откатывает на шкалу назад, промах на первой шкале отнимает жизнь.</div>\n</div>\n<div style=\"background: #1F1638; border-radius: 14px; padding: 16px\">\n<div style=\"font-family: 'Unbounded', sans-serif; font-size: 22px; font-weight: 800; color: #B57BFF\">90 секунд</div>\n<div style=\"color: #C7BBE6; font-size: 15px\">Не успел пройти все шкалы — рыба уходит.</div>\n</div>\n<div style=\"background: #1F1638; border-radius: 14px; padding: 16px\">\n<div style=\"font-family: 'Unbounded', sans-serif; font-size: 22px; font-weight: 800; color: #FFC857\">Бонус 10%</div>\n<div style=\"color: #C7BBE6; font-size: 15px\">Иногда появляется бонусная точка. Попади в неё и закончи игру — получишь сокровище.</div>\n</div>\n</div>\n</div>\n\n<div style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 18px; padding: 24px; display: flex; flex-direction: column; gap: 12px\">\n<h3 style=\"margin: 0; font-size: 20px; color: #FFFFFF\">Ранги рыбы</h3>\n<p style=\"margin: 0; color: #C7BBE6\">Чем выше ранг, тем реже рыба, больше очков и дороже продажа.</p>\n<div style=\"overflow-x: auto\">\n<table style=\"width: 100%; min-width: 420px; border-collapse: collapse; font-size: 15px\">\n<thead><tr style=\"text-align: left; color: #B9AED6\"><th style=\"padding: 10px 12px; border-bottom: 1px solid #2E2250\">Ранг</th><th style=\"padding: 10px 12px; border-bottom: 1px solid #2E2250\">Очки рыбака</th><th style=\"padding: 10px 12px; border-bottom: 1px solid #2E2250\">Продажа</th></tr></thead>\n<tbody>\n<template data-sc=\"for\" list=\"{{fishRanks}}\" as=\"r\" hint-placeholder-count=\"5\">\n<tr><td style=\"padding: 10px 12px; border-bottom: 1px solid #221839\"><span style=\"display: inline-flex; width: 36px; height: 36px; border-radius: 10px; border: 2px solid {{r.color}}; color: {{r.color}}; align-items: center; justify-content: center; font-family: 'Unbounded', sans-serif; font-weight: 800\">{{r.rank}}</span></td><td style=\"padding: 10px 12px; border-bottom: 1px solid #221839; color: #E2DAF5\">+{{r.xp}}</td><td style=\"padding: 10px 12px; border-bottom: 1px solid #221839; color: #E2DAF5\">{{r.sell}} монет</td></tr>\n</template>\n</tbody>\n</table>\n</div>\n</div>\n\n<div style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 18px; padding: 24px; display: flex; flex-direction: column; gap: 12px\">\n<h3 style=\"margin: 0; font-size: 20px; color: #FFFFFF\">Ранги рыбака</h3>\n<p style=\"margin: 0; color: #C7BBE6\">Все начинают с ранга D. Удача повышает шанс редкой рыбы (ранга B и выше).</p>\n<div style=\"overflow-x: auto\">\n<table style=\"width: 100%; min-width: 480px; border-collapse: collapse; font-size: 15px\">\n<thead><tr style=\"text-align: left; color: #B9AED6\"><th style=\"padding: 10px 12px; border-bottom: 1px solid #2E2250\">Ранг</th><th style=\"padding: 10px 12px; border-bottom: 1px solid #2E2250\">Очков до следующего</th><th style=\"padding: 10px 12px; border-bottom: 1px solid #2E2250\">Удача</th><th style=\"padding: 10px 12px; border-bottom: 1px solid #2E2250\">Шанс бонуса</th></tr></thead>\n<tbody>\n<template data-sc=\"for\" list=\"{{anglerRanks}}\" as=\"r\" hint-placeholder-count=\"6\">\n<tr><td style=\"padding: 10px 12px; border-bottom: 1px solid #221839; font-family: 'Unbounded', sans-serif; font-weight: 800; color: {{r.color}}\">{{r.rank}}</td><td style=\"padding: 10px 12px; border-bottom: 1px solid #221839; color: #E2DAF5\">{{r.need}}</td><td style=\"padding: 10px 12px; border-bottom: 1px solid #221839; color: #E2DAF5\">+{{r.luck}}%</td><td style=\"padding: 10px 12px; border-bottom: 1px solid #221839; color: #E2DAF5\">+{{r.bonus}}%</td></tr>\n</template>\n</tbody>\n</table>\n</div>\n<p style=\"margin: 0; color: #C7BBE6; font-size: 15px\">Очки сбрасываются после повышения. На SS очки копятся дальше: каждые 1000 дают ещё +1% удачи.</p>\n</div>\n\n<div style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 18px; padding: 24px; display: flex; flex-direction: column; gap: 12px\">\n<h3 style=\"margin: 0; font-size: 20px; color: #FFFFFF\">Биомы</h3>\n<p style=\"margin: 0; color: #C7BBE6\">Улов зависит от биома, где ты <b style=\"color: #FFFFFF\">стоишь</b> в момент заброса (не где поплавок). Биомы Terralith тоже учитываются. Равнины, леса и горы — это «Умеренные». Снежная тайга считается снежным биомом, обычная — умеренным.</p>\n<div style=\"display: flex; flex-wrap: wrap; gap: 8px\">\n<template data-sc=\"for\" list=\"{{biomeChips}}\" as=\"b\" hint-placeholder-count=\"9\">\n<span style=\"padding: 8px 14px; border-radius: 999px; background: #1F1638; color: #EFE8FF; font-weight: 600\">{{b.name}} <span style=\"color: #B9AED6\">· {{b.count}}</span></span>\n</template>\n</div>\n<p style=\"margin: 0; color: #B9AED6; font-size: 14px\">Число — сколько видов рыбы в биоме. У каждого биома свои рыбы, всего 132 вида.</p>\n</div>\n</div>\n</template>\n\n<template data-sc=\"if\" value=\"{{showFishList}}\" hint-placeholder-val=\"{{ false }}\">\n<div style=\"display: flex; flex-direction: column; gap: 20px\">\n<h2 style=\"margin: 0; font-family: 'Unbounded', sans-serif; font-size: 30px; color: #FFFFFF\">Рыбы</h2>\n<p style=\"margin: 0; color: #C7BBE6\">132 вида. Выбери биом. В игре свой прогресс смотри в <code style=\"color: #FF9FD8\">/kf catalog</code>.</p>\n<div role=\"tablist\" aria-label=\"Биом\" style=\"display: flex; flex-wrap: wrap; gap: 8px\">\n<template data-sc=\"for\" list=\"{{biomeTabs}}\" as=\"b\" hint-placeholder-count=\"9\">\n<button type=\"button\" role=\"tab\" aria-selected=\"{{b.selected}}\" onClick=\"{{b.pick}}\" style=\"padding: 9px 16px; min-height: 44px; border-radius: 999px; border: 1px solid {{b.border}}; background: {{b.bg}}; color: {{b.color}}; font: inherit; font-weight: 700; cursor: pointer\">{{b.name}}</button>\n</template>\n</div>\n<template data-sc=\"if\" value=\"{{fishEmpty}}\" hint-placeholder-val=\"{{ false }}\">\n<div style=\"background: #130D24; border: 1px dashed #4A3A78; border-radius: 18px; padding: 24px; color: #C7BBE6\">В горных биомах рыбы пока нет — она появится в следующих обновлениях.</div>\n</template>\n<div style=\"display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 10px\">\n<template data-sc=\"for\" list=\"{{fishList}}\" as=\"f\" hint-placeholder-count=\"15\">\n<div style=\"display: flex; align-items: center; gap: 12px; padding: 12px 14px; border-radius: 12px; background: #130D24; border: 1px solid #2E2250\">\n<span style=\"flex: 0 0 auto; width: 34px; height: 34px; border-radius: 9px; border: 2px solid {{f.color}}; color: {{f.color}}; display: flex; align-items: center; justify-content: center; font-family: 'Unbounded', sans-serif; font-size: 13px; font-weight: 800\">{{f.rank}}</span>\n<span style=\"font-weight: 600; color: #EFE8FF\">{{f.name}}</span>\n</div>\n</template>\n</div>\n</div>\n</template>\n\n<template data-sc=\"if\" value=\"{{showGear}}\" hint-placeholder-val=\"{{ false }}\">\n<div style=\"display: flex; flex-direction: column; gap: 22px\">\n<h2 style=\"margin: 0; font-family: 'Unbounded', sans-serif; font-size: 30px; color: #FFFFFF\">Удочки и снасти</h2>\n<p style=\"margin: 0; color: #C7BBE6\">Всё покупается в <code style=\"color: #FF9FD8\">/kf shop</code> за рыбацкие монеты — их даёт продажа рыбы. Удочку ранга X можно купить, когда твой ранг рыбака X или выше. Shift + ПКМ с удочкой открывает её меню, куда ставятся снасти.</p>\n\n<div style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 18px; padding: 24px; display: flex; flex-direction: column; gap: 12px\">\n<h3 style=\"margin: 0; font-size: 20px; color: #FFFFFF\">Удочки</h3>\n<p style=\"margin: 0; color: #C7BBE6; font-size: 15px\">Каждая удочка C–SS ускоряет прокачку ранга на 30%. Общий потолок ускорения — 60%. Удочка D — обычная, из крафта.</p>\n<div style=\"overflow-x: auto\">\n<table style=\"width: 100%; min-width: 520px; border-collapse: collapse; font-size: 15px\">\n<thead><tr style=\"text-align: left; color: #B9AED6\"><th style=\"padding: 10px 12px; border-bottom: 1px solid #2E2250\">Удочка</th><th style=\"padding: 10px 12px; border-bottom: 1px solid #2E2250\">Цена</th><th style=\"padding: 10px 12px; border-bottom: 1px solid #2E2250\">Слоты</th></tr></thead>\n<tbody>\n<template data-sc=\"for\" list=\"{{rods}}\" as=\"r\" hint-placeholder-count=\"6\">\n<tr><td style=\"padding: 10px 12px; border-bottom: 1px solid #221839; font-weight: 800; color: {{r.color}}\">{{r.name}}</td><td style=\"padding: 10px 12px; border-bottom: 1px solid #221839; color: #E2DAF5; white-space: nowrap\">{{r.price}}</td><td style=\"padding: 10px 12px; border-bottom: 1px solid #221839; color: #E2DAF5\">{{r.slots}}</td></tr>\n</template>\n</tbody>\n</table>\n</div>\n</div>\n\n<template data-sc=\"for\" list=\"{{partGroups}}\" as=\"pg\" hint-placeholder-count=\"6\">\n<div style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 18px; padding: 24px; display: flex; flex-direction: column; gap: 10px\">\n<div style=\"display: flex; flex-wrap: wrap; gap: 6px 12px; align-items: baseline\">\n<h3 style=\"margin: 0; font-size: 20px; color: #FFFFFF\">{{pg.title}}</h3>\n<span style=\"color: #B9AED6; font-size: 14px\">{{pg.note}}</span>\n</div>\n<div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 10px\">\n<template data-sc=\"for\" list=\"{{pg.items}}\" as=\"p\" hint-placeholder-count=\"3\">\n<div style=\"background: #1F1638; border-radius: 14px; padding: 14px 16px; display: flex; flex-direction: column; gap: 4px\">\n<div style=\"display: flex; justify-content: space-between; gap: 10px\"><span style=\"font-weight: 800; color: #FFFFFF\">{{p.name}}</span><span style=\"color: #FFC857; font-weight: 700; white-space: nowrap\">{{p.price}}</span></div>\n<span style=\"color: #C7BBE6; font-size: 15px\">{{p.effect}}</span>\n</div>\n</template>\n</div>\n</div>\n</template>\n</div>\n</template>\n\n<template data-sc=\"if\" value=\"{{showEnch}}\" hint-placeholder-val=\"{{ false }}\">\n<div style=\"display: flex; flex-direction: column; gap: 20px\">\n<h2 style=\"margin: 0; font-family: 'Unbounded', sans-serif; font-size: 30px; color: #FFFFFF\">Зачарования</h2>\n<p style=\"margin: 0; color: #C7BBE6\">73 собственных зачарования. Тир влияет на редкость: 1 — частые, 3 — редкие.</p>\n<div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 12px\">\n<div style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 16px; padding: 18px\"><div style=\"font-weight: 800; color: #FFFFFF\">Стол зачарований</div><div style=\"color: #C7BBE6; font-size: 15px\">Тир 2 — с кнопки от 10 уровней, тир 3 — от 30. Особые в столе не выпадают.</div></div>\n<div style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 16px; padding: 18px\"><div style=\"font-weight: 800; color: #FFFFFF\">Книги</div><div style=\"color: #C7BBE6; font-size: 15px\">Особые зачарования — только книгами: лут, рыбалка, торговля с библиотекарями (у каждого биома свои).</div></div>\n<div style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 16px; padding: 18px\"><div style=\"font-weight: 800; color: #FFFFFF\">Загадочная книга</div><div style=\"color: #C7BBE6; font-size: 15px\">ПКМ — выбор одной из 5 случайных книг. Одно бесплатное обновление списка.</div></div>\n<div style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 16px; padding: 18px\"><div style=\"font-weight: 800; color: #FFFFFF\">Кафедра расчарования</div><div style=\"color: #C7BBE6; font-size: 15px\">Пустая кафедра с книжными полками слева и справа. Снимает зачарование в книгу за 5/10/15 минут (по тиру), тратит книгу с пером.</div></div>\n<div style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 16px; padding: 18px\"><div style=\"font-weight: 800; color: #FFFFFF\">Наковальня</div><div style=\"color: #C7BBE6; font-size: 15px\">Ограничения «Слишком дорого» нет.</div></div>\n</div>\n<div role=\"tablist\" aria-label=\"Предмет\" style=\"display: flex; flex-wrap: wrap; gap: 8px\">\n<template data-sc=\"for\" list=\"{{enchFilters}}\" as=\"ef\" hint-placeholder-count=\"6\">\n<button type=\"button\" role=\"tab\" aria-selected=\"{{ef.selected}}\" onClick=\"{{ef.pick}}\" style=\"padding: 9px 16px; min-height: 44px; border-radius: 999px; border: 1px solid {{ef.border}}; background: {{ef.bg}}; color: {{ef.color}}; font: inherit; font-weight: 700; cursor: pointer\">{{ef.label}} <span style=\"opacity: 0.75\">{{ef.count}}</span></button>\n</template>\n</div>\n<div style=\"display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 12px\">\n<template data-sc=\"for\" list=\"{{enchList}}\" as=\"e\" hint-placeholder-count=\"12\">\n<div style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 16px; padding: 18px; display: flex; flex-direction: column; gap: 8px\">\n<div style=\"display: flex; flex-wrap: wrap; align-items: center; gap: 8px\">\n<span style=\"font-family: 'Unbounded', sans-serif; font-size: 16px; font-weight: 700; color: {{e.color}}\">{{e.name}}</span>\n<span style=\"color: #B9AED6; font-weight: 700\">{{e.max}}</span>\n</div>\n<div style=\"display: flex; flex-wrap: wrap; gap: 6px\">\n<span style=\"padding: 2px 9px; border-radius: 999px; background: #1F1638; color: {{e.color}}; font-size: 12px; font-weight: 700\">Тир {{e.tier}}</span>\n<template data-sc=\"if\" value=\"{{e.special}}\" hint-placeholder-val=\"{{ false }}\"><span style=\"padding: 2px 9px; border-radius: 999px; background: #3A1840; color: #FF9FD8; font-size: 12px; font-weight: 700\">Особое</span></template>\n<span style=\"padding: 2px 9px; border-radius: 999px; background: #1F1638; color: #C7BBE6; font-size: 12px; font-weight: 600\">{{e.types}}</span>\n</div>\n<span style=\"color: #D9CCF5; font-size: 15px\">{{e.desc}}</span>\n</div>\n</template>\n</div>\n</div>\n</template>\n\n<template data-sc=\"if\" value=\"{{showEcon}}\" hint-placeholder-val=\"{{ false }}\">\n<div style=\"display: flex; flex-direction: column; gap: 22px\">\n<h2 style=\"margin: 0; font-family: 'Unbounded', sans-serif; font-size: 30px; color: #FFFFFF\">Экономика</h2>\n<p style=\"margin: 0; color: #C7BBE6\">Деньги сервера — <b style=\"color: #FFFFFF\">AR</b>. Их тратят в магазине игроков и на награды за головы. Рыбацкие монеты — отдельная валюта только для рыбалки.</p>\n\n<div style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 18px; padding: 24px; display: flex; flex-direction: column; gap: 12px\">\n<div style=\"display: flex; flex-wrap: wrap; gap: 10px; align-items: baseline\"><h3 style=\"margin: 0; font-size: 20px; color: #FFFFFF\">Магазин игроков</h3><code style=\"color: #FF9FD8; font-weight: 700\">/ks</code></div>\n<div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 10px\">\n<div style=\"background: #1F1638; border-radius: 14px; padding: 14px 16px\"><div style=\"font-weight: 800; color: #FFFFFF\">Выставить лот</div><div style=\"color: #C7BBE6; font-size: 15px\">Возьми предмет в руку: <code style=\"color: #FF9FD8\">/ks add &lt;цена&gt; [кол-во]</code>. Цена за весь лот.</div></div>\n<div style=\"background: #1F1638; border-radius: 14px; padding: 14px 16px\"><div style=\"font-weight: 800; color: #FFFFFF\">Слоты</div><div style=\"color: #C7BBE6; font-size: 15px\">Покупаются: 1, 2, 4, 8 AR, дальше по 16 AR за каждый.</div></div>\n<div style=\"background: #1F1638; border-radius: 14px; padding: 14px 16px\"><div style=\"font-weight: 800; color: #FFFFFF\">7 дней</div><div style=\"color: #C7BBE6; font-size: 15px\">Столько лот висит в продаже, потом переходит во вкладку «Не продалось».</div></div>\n<div style=\"background: #1F1638; border-radius: 14px; padding: 14px 16px\"><div style=\"font-weight: 800; color: #FFFFFF\">Без налога</div><div style=\"color: #C7BBE6; font-size: 15px\">Продавец получает всю сумму, даже если был офлайн.</div></div>\n</div>\n</div>\n\n<div style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 18px; padding: 24px; display: flex; flex-direction: column; gap: 12px\">\n<div style=\"display: flex; flex-wrap: wrap; gap: 10px; align-items: baseline\"><h3 style=\"margin: 0; font-size: 20px; color: #FFFFFF\">Награды за головы</h3><code style=\"color: #FF9FD8; font-weight: 700\">/bounty</code><span style=\"color: #B9AED6; font-size: 14px\">или /hunt</span></div>\n<div style=\"display: flex; flex-direction: column; gap: 0\">\n<template data-sc=\"for\" list=\"{{bountyRules}}\" as=\"b\" hint-placeholder-count=\"6\">\n<div style=\"display: flex; gap: 12px; padding: 10px 0; border-bottom: 1px solid #221839\">\n<span style=\"flex: 0 0 auto; width: 8px; height: 8px; margin-top: 9px; border-radius: 2px; background: #B57BFF\"></span>\n<span style=\"color: #E2DAF5\">{{b.t}}</span>\n</div>\n</template>\n</div>\n</div>\n\n<div style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 18px; padding: 24px; display: flex; flex-direction: column; gap: 8px\">\n<div style=\"display: flex; flex-wrap: wrap; gap: 10px; align-items: baseline\"><h3 style=\"margin: 0; font-size: 20px; color: #FFFFFF\">Починка опытом</h3><code style=\"color: #FF9FD8; font-weight: 700\">/mending &lt;уровни&gt;</code></div>\n<p style=\"margin: 0; color: #C7BBE6\">Тратит уровни опыта на починку всех предметов с Починкой в инвентаре — как если бы ты собирал опыт.</p>\n</div>\n</div>\n</template>\n\n<template data-sc=\"if\" value=\"{{showTops}}\" hint-placeholder-val=\"{{ false }}\">\n<div style=\"display: flex; flex-direction: column; gap: 22px\">\n<h2 style=\"margin: 0; font-family: 'Unbounded', sans-serif; font-size: 30px; color: #FFFFFF\">Топы</h2>\n<p style=\"margin: 0; color: #C7BBE6\">Меню топов открывается командой <code style=\"color: #FF9FD8\">/topmenu</code>.</p>\n<div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 12px\">\n<template data-sc=\"for\" list=\"{{tops}}\" as=\"t\" hint-placeholder-count=\"5\">\n<div style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 16px; padding: 18px; display: flex; flex-direction: column; gap: 4px\">\n<span style=\"font-weight: 800; color: {{t.color}}; font-size: 18px\">{{t.name}}</span>\n<span style=\"color: #C7BBE6; font-size: 15px\">{{t.stat}}</span>\n</div>\n</template>\n</div>\n<div style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 18px; padding: 20px 24px; display: flex; flex-wrap: wrap; gap: 6px 14px; align-items: baseline\">\n<code style=\"color: #FF9FD8; font-weight: 700\">/topmenu kills</code>\n<span style=\"color: #E2DAF5\">Топ по убийствам игроков — только в чате, в меню его нет.</span>\n</div>\n</div>\n</template>\n\n<template data-sc=\"if\" value=\"{{showCmd}}\" hint-placeholder-val=\"{{ false }}\">\n<div style=\"display: flex; flex-direction: column; gap: 22px\">\n<h2 style=\"margin: 0; font-family: 'Unbounded', sans-serif; font-size: 30px; color: #FFFFFF\">Команды</h2>\n<p style=\"margin: 0; color: #C7BBE6\">Команды с пометкой <span style=\"padding: 1px 8px; border-radius: 999px; background: #3A2A10; color: #FFD48A; font-size: 13px; font-weight: 700\">уточнить</span> — черновик, их ещё нужно сверить с сервером.</p>\n<template data-sc=\"for\" list=\"{{cmdGroups}}\" as=\"grp\" hint-placeholder-count=\"4\">\n<div style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 18px; padding: 24px; display: flex; flex-direction: column; gap: 4px\">\n<h3 style=\"margin: 0 0 8px; font-size: 20px; color: #FFFFFF\">{{grp.title}}</h3>\n<template data-sc=\"for\" list=\"{{grp.rows}}\" as=\"c\" hint-placeholder-count=\"5\">\n<div style=\"display: flex; flex-wrap: wrap; gap: 6px 14px; align-items: baseline; padding: 10px 0; border-bottom: 1px solid #221839\">\n<code style=\"flex: 0 0 230px; color: #FF9FD8; font-weight: 700\">{{c.cmd}}</code>\n<span style=\"flex: 1 1 240px; color: #E2DAF5\">{{c.desc}}</span>\n<template data-sc=\"if\" value=\"{{c.check}}\" hint-placeholder-val=\"{{ false }}\">\n<span style=\"padding: 1px 8px; border-radius: 999px; background: #3A2A10; color: #FFD48A; font-size: 13px; font-weight: 700\">уточнить</span>\n</template>\n</div>\n</template>\n</div>\n</template>\n</div>\n</template>\n\n<template data-sc=\"if\" value=\"{{showDonate}}\" hint-placeholder-val=\"{{ false }}\">\n<div style=\"display: flex; flex-direction: column; gap: 22px\">\n<h2 style=\"margin: 0; font-family: 'Unbounded', sans-serif; font-size: 30px; color: #FFFFFF\">Донат: K.Oins, VIP, питомцы</h2>\n<div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 16px\">\n<div style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 18px; padding: 24px; display: flex; flex-direction: column; gap: 10px\">\n<h3 style=\"margin: 0; font-size: 20px; color: #FFFFFF\">K.Oins</h3>\n<p style=\"margin: 0; color: #C7BBE6\">Донатная валюта. Покупается на сайте от 100 штук, 1 K.Oin = 0,5 ₽. Тратится на префикс (500), роль в Discord (1000) и кейс с питомцами (100).</p>\n</div>\n<div style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 18px; padding: 24px; display: flex; flex-direction: column; gap: 10px\">\n<h3 style=\"margin: 0; font-size: 20px; color: #FFFFFF\">VIP</h3>\n<p style=\"margin: 0; color: #C7BBE6\">На 1, 3 или 6 месяцев. [Что даёт VIP — список возможностей.]</p>\n</div>\n</div>\n<img src=\"/assets/hero.jpg\" alt=\"Питомец — летучая мышь\" style=\"width: 100%; aspect-ratio: 16 / 6; object-fit: cover; border-radius: 20px; border: 1px solid #2E2250; display: block\">\n<h3 style=\"margin: 0; font-size: 22px; color: #FFFFFF\">Питомцы</h3>\n<p style=\"margin: 0; color: #C7BBE6\">Шесть рангов. Получить — из кейса с питомцами или купить случайного питомца нужного ранга.</p>\n<div style=\"display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 12px\">\n<template data-sc=\"for\" list=\"{{petRanks}}\" as=\"r\" hint-placeholder-count=\"6\">\n<div style=\"background: #130D24; border: 1px solid #2E2250; border-radius: 16px; padding: 16px; display: flex; flex-direction: column; gap: 8px\">\n<span style=\"width: 48px; height: 48px; border-radius: 12px; border: 2px solid {{r.color}}; color: {{r.color}}; display: flex; align-items: center; justify-content: center; font-family: 'Unbounded', sans-serif; font-size: 20px; font-weight: 800\">{{r.rank}}</span>\n<span style=\"font-size: 14px; color: #C7BBE6\">[Питомцы и бонусы ранга]</span>\n</div>\n</template>\n</div>\n<a href=\"Donate.dc.html\" style=\"align-self: flex-start; padding: 14px 22px; border-radius: 12px; background: #8B3DFF; color: #FFFFFF; text-decoration: none; font-weight: 700\">Открыть донат</a>\n</div>\n</template>\n\n</div>\n</section>\n\n<footer style=\"background: #08060F; border-top: 1px solid #241A40\">\n<div style=\"max-width: 1240px; margin: 0 auto; padding: 32px 24px; display: flex; flex-wrap: wrap; gap: 16px; justify-content: space-between; color: #B9AED6; font-size: 14px\">\n<span>© 2026 Komori · mc.komori.fun · Не связан с Mojang и Microsoft.</span>\n<span style=\"display: flex; gap: 20px; flex-wrap: wrap\"><a href=\"/rules\">Правила</a><a href=\"/wiki\">Вики</a><a href=\"/map\">Карта</a><a href=\"{{K.launcher}}\">Лаунчер</a><a href=\"{{K.discord}}\" target=\"_blank\" rel=\"noopener\">Discord</a></span>\n</div>\n</footer>\n\n</div>\n</template><x-dc></x-dc>\n<script type=\"text/x-dc\" data-dc-script>\nclass Component extends DCLogic {\nconstructor(props) {\nsuper(props);\nthis.state = { tab: 'fish', biome: 0, ef: 'all' };\n}\nrenderVals() {\nvar self = this;\nvar rc = { D: '#A9A2C0', C: '#7BD88F', B: '#6FA8FF', A: '#C99BFF', S: '#FFC857', SS: '#FF7EDB' };\nvar tierColor = { 1: '#7BD88F', 2: '#6FA8FF', 3: '#FFC857' };\nvar tabs = [\n{ id: 'fish', label: 'Рыбалка', hint: 'мини-игра, ранги, биомы' },\n{ id: 'fishlist', label: 'Рыбы', hint: '132 вида по биомам' },\n{ id: 'gear', label: 'Удочки и снасти', hint: 'цены и эффекты' },\n{ id: 'ench', label: 'Зачарования', hint: '73 зачарования' },\n{ id: 'econ', label: 'Экономика', hint: 'магазин, награды, починка' },\n{ id: 'tops', label: 'Топы', hint: 'рейтинги игроков' },\n{ id: 'cmd', label: 'Команды', hint: 'все команды игрока' }\n];\nvar FISH = [[\"Снежные\",[[\"Йормунганд\",\"S\"],[\"Аврора\",\"A\"],[\"Нарвал\",\"A\"],[\"Багряная форель\",\"B\"],[\"Ледяная щука\",\"B\"],[\"Арктический голец\",\"C\"],[\"Палтус\",\"C\"],[\"Сиг\",\"C\"],[\"Хариус\",\"C\"],[\"Корюшка\",\"D\"],[\"Мойва\",\"D\"],[\"Навага\",\"D\"],[\"Пикша\",\"D\"]]],[\"Океан\",[[\"Левиафан\",\"S\"],[\"Золотой марлин\",\"A\"],[\"Рыба капля\",\"A\"],[\"Барракуда\",\"B\"],[\"Рифовый окунь\",\"B\"],[\"Рыба меч\",\"B\"],[\"Камбала\",\"C\"],[\"Морской лещ\",\"C\"],[\"Мурена\",\"C\"],[\"Тунец\",\"C\"],[\"Анчоус\",\"D\"],[\"Морской карась\",\"D\"],[\"Сардина\",\"D\"],[\"Сельдь\",\"D\"],[\"Скумбрия\",\"D\"]]],[\"Умеренные\",[[\"Рыба феникс\",\"S\"],[\"Золотой кои\",\"A\"],[\"Лесной стример\",\"A\"],[\"Лиственный жерех\",\"B\"],[\"Лиственный сом\",\"B\"],[\"Рассветная форель\",\"B\"],[\"Карп\",\"C\"],[\"Линь\",\"C\"],[\"Судак\",\"C\"],[\"Щука\",\"C\"],[\"Голавль\",\"D\"],[\"Красноперка\",\"D\"],[\"Окунь\",\"D\"],[\"Плотва\",\"D\"],[\"Уклейка\",\"D\"]]],[\"Пустыня\",[[\"Себек\",\"S\"],[\"Песчаная змеерыба\",\"A\"],[\"Рыба мираж\",\"A\"],[\"Золотая арована\",\"B\"],[\"Нильский окунь\",\"B\"],[\"Рыба Голиаф\",\"B\"],[\"Клариас\",\"C\"],[\"Лабео\",\"C\"],[\"Слоновая рыба\",\"C\"],[\"Тилапия\",\"C\"],[\"Аплохейлус\",\"D\"],[\"Бычок\",\"D\"],[\"Гамбузия\",\"D\"],[\"Киллифиш\",\"D\"],[\"Щенок пустыни\",\"D\"]]],[\"Джунгли\",[[\"Йара\",\"S\"],[\"Арапайма\",\"A\"],[\"Самоцветный дискус\",\"A\"],[\"Красная пиранья\",\"B\"],[\"Тукунаре\",\"B\"],[\"Электрический угорь\",\"B\"],[\"Кардинальная тетра\",\"C\"],[\"Оскар\",\"C\"],[\"Паку\",\"C\"],[\"Скалярия\",\"C\"],[\"Барбус\",\"D\"],[\"Гуппи\",\"D\"],[\"Данио\",\"D\"],[\"Меченосец\",\"D\"],[\"Неоновая тетра\",\"D\"]]],[\"Болото\",[[\"Лернейская гидра\",\"S\"],[\"Блуждающий огонёк\",\"A\"],[\"Топяной оборотень\",\"A\"],[\"Аллигаторовый панцирник\",\"B\"],[\"Ведьмин сом\",\"B\"],[\"Змееголов\",\"B\"],[\"Вьюн\",\"C\"],[\"Налим\",\"C\"],[\"Сом\",\"C\"],[\"Угорь\",\"C\"],[\"Верховка\",\"D\"],[\"Гольян\",\"D\"],[\"Горчак\",\"D\"],[\"Ротан\",\"D\"],[\"Серебряный карась\",\"D\"]]],[\"Грибные\",[[\"Лох-Несс\",\"S\"],[\"Грибоглаз\",\"A\"],[\"Колпачок фей\",\"A\"],[\"Грибной сом\",\"B\"],[\"Спороносный угорь\",\"B\"],[\"Ёрш\",\"C\"],[\"Елец\",\"C\"],[\"Подуст\",\"C\"],[\"Язь\",\"C\"],[\"Белоглазка\",\"D\"],[\"Пескарь\",\"D\"],[\"Подкаменщик\",\"D\"],[\"Ряпушка\",\"D\"],[\"Чехонь\",\"D\"]]],[\"Пещеры\",[[\"Василиск\",\"S\"],[\"Кристальный призрак\",\"A\"],[\"Лазуритовая рыба\",\"A\"],[\"Светящийся следопыт\",\"B\"],[\"Сталактитовый иглобрюх\",\"B\"],[\"Хрустальная тень\",\"B\"],[\"Амблиопсис\",\"C\"],[\"Безглазка\",\"C\"],[\"Люцифуга\",\"C\"],[\"Слепая тетра\",\"C\"],[\"Гарра\",\"D\"],[\"Молли\",\"D\"],[\"Слепой сомик\",\"D\"],[\"Слепой угорь\",\"D\"],[\"Фреатихт\",\"D\"]]],[\"Глубокая тьма\",[[\"Кракен бездны\",\"S\"],[\"Сумеречный призрак\",\"A\"],[\"Тенерыба\",\"A\"],[\"Призрачный скат\",\"B\"],[\"Телескопическая рыба\",\"B\"],[\"Тёмная дракон-рыба\",\"B\"],[\"Большерот\",\"C\"],[\"Мешкорот\",\"C\"],[\"Рыба удильщик\",\"C\"],[\"Рыба-гадюка\",\"C\"],[\"Макрурус\",\"D\"],[\"Рыба топорик\",\"D\"],[\"Угольная рыба\",\"D\"],[\"Фонарик\",\"D\"],[\"Циклотон\",\"D\"]]]];\nvar ENCH = [[\"Адреналин\",1,3,\"поножи\",0,\"При низком здоровье даёт Скорость.\"],[\"Антигравитация\",2,3,\"меч/топор/копьё/лук/ботинки\",1,\"Подбрасывает цель левитацией.\"],[\"Бриз\",3,3,\"меч\",1,\"Запускает ветряной заряд при замахе (кд 5 сек).\"],[\"Бульдозер\",3,3,\"кирка/лопата\",1,\"Ломает блоки вокруг добытого: ур.1 — один ниже, ур.2 — крестом (выше, ниже, левее, правее), ур.3 — область 3x3. При приседании не работает.\"],[\"Вечная мерзлота\",2,1,\"шлем/нагрудник/поножи/ботинки\",1,\"Замораживает атакующего.\"],[\"Галлюцинации\",1,3,\"меч/топор/копьё\",0,\"Вызывает тошноту, мобы вокруг начинают бить друг друга.\"],[\"Глаза Эндера\",3,1,\"шлем\",1,\"Эндермены не нападают на вас.\"],[\"Головокружение\",1,3,\"меч/топор/копьё\",0,\"Дезориентирует цель.\"],[\"Гравитация\",3,3,\"меч/топор/лук\",0,\"Стягивает и подбрасывает мобов вокруг цели (кд 0,8 сек).\"],[\"Гром\",3,4,\"меч/топор/копьё\",0,\"Бьёт молнией в цель и наносит урон окружающим (откат 180 сек).\"],[\"Губка\",2,1,\"нагрудник\",0,\"Связан с водой.\"],[\"Драконий\",3,1,\"элитры\",1,\"Огненная атака в стиле дракона (кд 1,5 сек).\"],[\"Жатва\",2,1,\"мотыга\",1,\"Мотыга не ломает несозревший урожай: срезаются только созревшие культуры.\"],[\"Заземление\",3,1,\"ботинки\",0,\"Даёт иммунитет к левитации, в ответ бьёт молнией.\"],[\"Заморозка\",1,3,\"лук\",0,\"Замораживает цель стрелой.\"],[\"Заражение\",2,3,\"нагрудник\",0,\"Вызывает мобов против атакующего.\"],[\"Засев\",2,1,\"мотыга\",1,\"После сбора урожая на его месте сразу вырастает новый росток. Тратится одно семя (плод) собранной культуры.\"],[\"Иглы\",2,2,\"копьё\",1,\"Вонзает иглы (стрелы) в цель (кд 30 сек).\"],[\"Извержение\",3,3,\"шлем\",0,\"Огненный выброс в ответ на урон.\"],[\"Измельчение\",2,1,\"кирка/топор/лопата/мотыга\",0,\"Дробит блоки.\"],[\"Искусность\",2,1,\"меч/топор/копьё\",1,\"Метательная атака при использовании предмета.\"],[\"Исцеление\",2,1,\"лук\",0,\"Стрела лечит цель.\"],[\"Каменный леденец\",2,1,\"кирка\",0,\"Руда при добыче восстанавливает сытость и с шансом даёт короткий бафф (дроп сохраняется).\"],[\"Критичность\",2,2,\"копьё\",0,\"С шансом наносит критический удар с двойным уроном.\"],[\"Кровопийца\",2,5,\"меч/копьё\",0,\"Возвращает здоровье за нанесённый урон.\"],[\"Крылья\",3,1,\"нагрудник\",1,\"Двойной прыжок: ваша настоящая элитра из инвентаря сама надевается вместо нагрудника, при приземлении всё возвращается на места. Износ в полёте идёт на элитру.\"],[\"Крюк\",3,1,\"лук\",0,\"Стрела работает как крюк.\"],[\"Лунный\",2,1,\"элитры\",0,\"Эффект при приседании в полёте (кд 1 сек).\"],[\"Магнетизм\",2,1,\"кирка/топор/лопата/мотыга\",1,\"Добытые блоки сразу попадают в инвентарь, при полном инвентаре падают под ноги. Содержимое хранилищ выпадает как в ваниле, сам контейнер идёт в инвентарь.\"],[\"Магнитное поле\",1,1,\"шлем/нагрудник/поножи/ботинки\",0,\"Приседание притягивает предметы, железных големов, вагонетки и мобов с железом (радиус растёт с числом частей). Полный комплект: двойной прыжок включает левитацию.\"],[\"Метель\",3,3,\"меч\",1,\"Запускает ледяной заряд при замахе (кд 7 сек).\"],[\"Метеор\",3,2,\"меч\",1,\"Запускает метеорит при использовании (кд 6 сек). Взрыв не ломает блоки.\"],[\"Морская походка\",2,1,\"поножи\",1,\"Эффект в воде.\"],[\"Нестабильность\",2,5,\"нагрудник\",0,\"Взрыв рядом при ударе по вам, урон 5 (откат 180 сек).\"],[\"Нитро\",2,5,\"лук\",1,\"Стрела взрывается через время. Взрыв наносит урон, но не ломает блоки.\"],[\"Ночной глаз\",2,1,\"шлем\",0,\"Даёт ночное зрение.\"],[\"Обморожение\",1,5,\"меч/копьё/топор\",0,\"Замораживает цель при ударе.\"],[\"Огненная поступь\",3,3,\"ботинки\",0,\"Позволяет ходить по лаве.\"],[\"Отталкивание\",1,3,\"поножи\",0,\"Отталкивает атакующего.\"],[\"Перелом\",1,4,\"топор\",1,\"Ломает броню цели.\"],[\"Плавка\",3,1,\"кирка/топор/лопата/мотыга\",1,\"Сразу переплавляет добытые блоки.\"],[\"Пламя\",3,3,\"меч\",1,\"Запускает огненный шар при замахе (кд 5 сек).\"],[\"Планирование\",3,1,\"ботинки\",1,\"Медленное падение в воздухе.\"],[\"Побег\",2,1,\"ботинки\",0,\"При низком здоровье телепортирует вас прочь от врага.\"],[\"Поглощение\",1,3,\"нагрудник\",0,\"При получении урона (шанс; откат 180 сек) даёт поглощение и гасит удар.\"],[\"Подъём\",2,2,\"элитры\",0,\"Помогает набирать высоту в полёте.\"],[\"Пожирание\",1,4,\"меч/топор/копьё\",1,\"Убийство моба даёт 1 ед. сытости (откат 5 сек) и поглощает дроп. При полной сытости работает как обычно.\"],[\"Покоритель волн\",3,2,\"ботинки\",1,\"Позволяет бегать по воде.\"],[\"Прокол\",2,1,\"копьё\",0,\"Пробивающий удар (кд 4 сек).\"],[\"Противоядие\",1,4,\"нагрудник\",0,\"Защищает от отравления, иссушения и слепоты.\"],[\"Прыгучесть\",1,3,\"поножи\",0,\"Усиливает прыжок.\"],[\"Разряд\",2,3,\"нагрудник\",1,\"Наносит ответный урон врагам вокруг при ударе по вам (откат 180 сек).\"],[\"Расплав\",1,3,\"шлем/нагрудник/поножи/ботинки\",1,\"Поджигает атакующего.\"],[\"Рикошет\",3,3,\"лук\",0,\"Стрела отскакивает на другую цель рядом.\"],[\"Рывок\",2,1,\"ботинки\",1,\"При начале бега даёт Скорость II на 10 сек (откат 15 сек).\"],[\"Самонаведение\",3,1,\"лук\",0,\"Стрела летит в цель.\"],[\"Скопление\",2,3,\"кирка/топор\",1,\"Ломает за раз связанные одинаковые блоки. Кирка: 5 / 10 / 15 блоков руды и камня, топор: 20 / 50 / 128 блоков дерева. Тратит прочность за каждый блок. При приседании не работает.\"],[\"Скрытность\",2,3,\"поножи\",0,\"Когда после удара остаётся 1-3 ХП: на 15 сек невидимость (мобы не видят), Скорость IV и Слабость II. Откат 180 сек.\"],[\"Солнечный\",2,1,\"элитры\",0,\"Эффект при приседании в полёте (кд 1 сек).\"],[\"Талант\",2,5,\"кирка/топор/меч/копьё\",0,\"Увеличивает получаемый опыт.\"],[\"Телосложение\",1,5,\"шлем\",0,\"При низком здоровье даёт Сопротивление.\"],[\"Токсичность\",1,1,\"шлем/нагрудник/поножи/ботинки\",0,\"Атакующий получает яд и иссушение.\"],[\"Торможение\",2,1,\"элитры\",0,\"Снижает получаемый урон.\"],[\"Тьма\",1,4,\"меч/топор/копьё\",0,\"Накладывает слепоту на цель.\"],[\"Тяга\",2,1,\"элитры\",0,\"Усиливает ускорение элитрами.\"],[\"Увядание\",3,3,\"меч/топор/копьё\",1,\"Накладывает иссушение на цель.\"],[\"Улей\",2,3,\"нагрудник\",0,\"При ударе по вам вызывает пчёл, которые атакуют обидчика.\"],[\"Фантом\",2,1,\"меч\",0,\"Даёт невидимость после удара и усиливает урон.\"],[\"Черепа\",3,2,\"меч\",1,\"Запускает череп иссушителя (кд 5 сек).\"],[\"Чума\",2,5,\"шлем/нагрудник/поножи/ботинки\",0,\"Накладывает негативные эффекты на атакующих.\"],[\"Шипы\",2,1,\"нагрудник\",1,\"Вонзает шипы (стрелы) в атакующего.\"],[\"Яд\",1,5,\"меч/топор/копьё/лук\",1,\"Накладывает яд и иссушение.\"],[\"Ярость\",2,5,\"нагрудник\",0,\"При низком здоровье даёт Силу (кд 6 сек).\"]];\nvar ROMAN = ['', 'I', 'I–II', 'I–III', 'I–IV', 'I–V'];\nvar filters = [\n{ id: 'all', label: 'Все', words: null },\n{ id: 'melee', label: 'Оружие', words: ['меч', 'топор', 'копьё'] },\n{ id: 'bow', label: 'Лук', words: ['лук'] },\n{ id: 'armor', label: 'Броня', words: ['шлем', 'нагрудник', 'поножи', 'ботинки'] },\n{ id: 'tools', label: 'Инструменты', words: ['кирка', 'лопата', 'мотыга', 'топор'] },\n{ id: 'elytra', label: 'Элитры', words: ['элитры'] }\n];\nfunction match(e, f) {\nif (!f.words) return true;\nvar ts = e[3].split('/');\nfor (var i = 0; i < f.words.length; i++) { if (ts.indexOf(f.words[i]) >= 0) return true; }\nreturn false;\n}\nvar curF = filters.filter(function (f) { return f.id === self.state.ef; })[0] || filters[0];\nvar cur = FISH[this.state.biome] || FISH[0];\nfunction chip(on) { return { bg: on ? '#8B3DFF' : '#170F2B', border: on ? '#8B3DFF' : '#2E2250', color: on ? '#FFFFFF' : '#C7BBE6', selected: on ? 'true' : 'false' }; }\nfunction part(name, price, effect) { return { name: name, price: price + ' мон.', effect: effect }; }\nfunction row(c, d, check) { return { cmd: c, desc: d, check: !!check }; }\nreturn {\ntabs: tabs.map(function (t) {\nvar on = t.id === self.state.tab;\nreturn { label: t.label, hint: t.hint, current: on ? 'page' : 'false',\nbg: on ? '#8B3DFF' : 'transparent', color: on ? '#FFFFFF' : '#EFE8FF', sub: on ? '#EBDDFF' : '#B9AED6',\npick: function () { self.setState({ tab: t.id }); } };\n}),\nshowFish: this.state.tab === 'fish',\nshowFishList: this.state.tab === 'fishlist',\nshowGear: this.state.tab === 'gear',\nshowEnch: this.state.tab === 'ench',\nshowEcon: this.state.tab === 'econ',\nshowTops: this.state.tab === 'tops',\nshowCmd: this.state.tab === 'cmd',\nshowDonate: this.state.tab === 'donate',\nfishRanks: [['D', 3, 10], ['C', 5, 25], ['B', 9, 60], ['A', 18, 150], ['S', 36, 400]].map(function (r) { return { rank: r[0], xp: r[1], sell: r[2], color: rc[r[0]] }; }),\nanglerRanks: [['D', '190', 0, 0], ['C', '560', 1, 0], ['B', '1250', 2, 0], ['A', '2500', 3, 0.5], ['S', '5000', 4, 1], ['SS', 'последний ранг', 5, 2]].map(function (r) { return { rank: r[0], need: r[1], luck: r[2], bonus: r[3], color: rc[r[0]] }; }),\nbiomeChips: FISH.map(function (b) { return { name: b[0], count: b[1].length }; }),\nbiomeTabs: FISH.map(function (b, i) {\nvar c = chip(i === self.state.biome);\nc.name = b[0]; c.pick = function () { self.setState({ biome: i }); };\nreturn c;\n}),\nfishList: cur[1].map(function (f) { return { name: f[0], rank: f[1], color: rc[f[1]] }; }),\nfishEmpty: cur[1].length === 0,\nrods: [\n['Удочка D', 'крафт', 'Нет слотов и бонусов', 'D'],\n['Удочка рыбака C', '500 мон.', 'Наживка', 'C'],\n['Удочка рыбака B', '1 500 мон.', 'Наживка, крючок, 1 модификатор', 'B'],\n['Удочка рыбака A', '3 500 мон.', 'Наживка, крючок, леска, 1 модификатор', 'A'],\n['Удочка рыбака S', '7 000 мон.', 'Наживка, крючок, леска, поплавок, 2 модификатора', 'S'],\n['Удочка рыбака SS', '14 000 мон.', 'Наживка, крючок, леска, поплавок, грузик, 3 модификатора', 'SS']\n].map(function (r) { return { name: r[0], price: r[1], slots: r[2], color: rc[r[3]] }; }),\npartGroups: [\n{ title: 'Наживка', note: 'тратится по 1 за поимку', items: [part('Червь', 4, '+15% к шансу рыбы рангов D и C'), part('Ракушка', 6, '+20% к шансу океанской рыбы'), part('Золотая наживка', 20, '+10% к шансу рыбы рангов A и S')] },\n{ title: 'Крючки', note: 'на 150 поимок', items: [part('Железный крючок', 150, '+1 жизнь в мини-игре'), part('Острый крючок', 400, 'Зелёная зона шире на 1 клетку'), part('Золотой крючок', 600, '+5% к шансу бонусной точки')] },\n{ title: 'Лески', note: 'на 150 поимок', items: [part('Нейлоновая леска', 150, 'Ползунок двигается медленнее'), part('Прочная леска', 300, '+15 секунд на игру'), part('Шёлковая леска', 700, 'Ползунок медленнее и +10 секунд')] },\n{ title: 'Поплавки', note: 'на 150 поимок', items: [part('Светящийся поплавок', 800, 'Бонусная зона шире на 1 клетку'), part('Тяжёлый поплавок', 1200, '+2% к шансу редкой рыбы')] },\n{ title: 'Грузики', note: 'на 150 поимок', items: [part('Свинцовый грузик', 1000, '+10% очков рыбака'), part('Глубинный грузик', 1500, '+12% к шансу рыбы рангов B, A и S')] },\n{ title: 'Модификаторы', note: 'вечные', items: [part('Монетка удачи', 3000, '+3% к шансу редкой рыбы'), part('Двойной улов', 5000, '10% шанс поймать вторую рыбу'), part('Бережливость', 2500, '25% шанс не потратить наживку'), part('Нюх на клады', 3500, '+5% к шансу бонусной точки')] }\n],\nenchFilters: filters.map(function (f) {\nvar c = chip(f.id === curF.id);\nc.label = f.label; c.count = ENCH.filter(function (e) { return match(e, f); }).length;\nc.pick = function () { self.setState({ ef: f.id }); };\nreturn c;\n}),\nenchList: ENCH.filter(function (e) { return match(e, curF); }).map(function (e) {\nreturn { name: e[0], tier: e[1], max: ROMAN[e[2]] || '', types: e[3].split('/').join(', '), special: !!e[4], desc: e[5], color: tierColor[e[1]] };\n}),\nbountyRules: [\n'Назначь награду за голову любого игрока, который заходил на сервер. Минимум 25 AR.',\n'Можно сделать анонимный заказ: имя скрыто, сверху берётся 20 AR.',\n'Охотник сдаёт голову цели во вкладке «Заказы» и сразу получает награду, голова уходит заказчику.',\n'Заказ живёт 7 дней. Не выполнен — 100% возврата. Отменишь сам — вернётся 90%.',\n'Если цель убила заказчика, она может сдать его голову и забрать награду себе.',\n'Нельзя заказать себя или выполнить свой же заказ. Подделать голову не выйдет: проверяется по игроку, а не по названию.'\n].map(function (t) { return { t: t }; }),\ntops: [\n['Онлайн', 'Время на сервере', '#7CE0FF'],\n['Смерти', 'Количество смертей', '#FF8A8A'],\n['Баланс', 'Сколько AR на счету', '#8CFF9E'],\n['Рыбалка', 'Ранг и очки рыбака', '#7FDBFF'],\n['Охотники', 'Выполненные заказы на головы', '#FFB366']\n].map(function (t) { return { name: t[0], stat: t[1], color: t[2] }; }),\ncmdGroups: [\n{ title: 'Рыбалка', rows: [\nrow('/kf catalog', 'Каталог: какие рыбы ты поймал по биомам и рангам'),\nrow('/kf shop', 'Магазин рыбака: продажа рыбы, удочки и снасти'),\nrow('/kf balance', 'Сколько у тебя рыбацких монет'),\nrow('Shift + ПКМ удочкой', 'Меню удочки — поставить снасти')\n] },\n{ title: 'Экономика', rows: [\nrow('/ks', 'Магазин игроков'),\nrow('/ks add <цена> [кол-во]', 'Выставить предмет из руки на продажу'),\nrow('/bounty', 'Награды за головы (также /hunt)'),\nrow('/mending <уровни>', 'Починить предметы с Починкой за уровни опыта')\n] },\n{ title: 'Топы', rows: [\nrow('/topmenu', 'Меню всех топов'),\nrow('/topmenu kills', 'Топ убийств игроков в чат')\n] },\n{ title: 'Общие', rows: [\nrow('/msg <ник> <текст>', 'Личное сообщение', true),\nrow('/r <текст>', 'Ответить на последнее личное сообщение', true),\nrow('/link <код>', 'Привязать ник к аккаунту на сайте', true)\n] }\n],\npetRanks: ['D', 'C', 'B', 'A', 'S', 'SS'].map(function (r) { return { rank: r, color: rc[r] }; })\n};\n}\n}\n</script>\n</body>\n</html>\n"};
const ASSETS = {"favicon.png":{"type":"image/png","b64":""},"hero.jpg":{"type":"image/jpeg","b64":""},"logo.png":{"type":"image/png","b64":""}};
const RUNTIME = "/* Общие значения для шапки и подвала всех страниц ({{K.*}}).\n * window.KOMORI приходит от сервера: { me, page, cfg: { discord, launcher, map }, flash }. */\n(function () {\n  'use strict';\n  var NAV = [\n    { id: 'main', label: 'Главная', href: '/' },\n    { id: 'rules', label: 'Правила', href: '/rules' },\n    { id: 'wiki', label: 'Вики', href: '/wiki' },\n    { id: 'map', label: 'Карта', href: '/map' }\n  ];\n  window.KomoriBase = function () {\n    var k = window.KOMORI || {}, me = k.me, cfg = k.cfg || {};\n    return {\n      loggedIn: !!me, loggedOut: !me,\n      name: me ? me.name : '',\n      avatar: me ? me.avatar : '',\n      loginUrl: '/auth/login?next=' + encodeURIComponent(location.pathname),\n      logout: function () {\n        fetch('/auth/logout', { method: 'POST' }).finally(function () { location.href = '/'; });\n      },\n      nav: NAV.map(function (n) {\n        var on = n.id === k.page;\n        return { label: n.label, href: n.href, current: on ? 'page' : 'false', bg: on ? '#8B3DFF' : 'transparent', color: on ? '#FFFFFF' : '#C7BBE6' };\n      }),\n      discord: cfg.discord, launcher: cfg.launcher, map: cfg.map,\n      flash: k.flash || '', flashJoin: k.flash === 'Сначала зайди на наш сервер Discord, потом войди на сайт.'\n    };\n  };\n})();\n\n/* Komori — маленький движок страниц сайта.\n * Понимает разметку макетов: <x-dc> с шаблоном, {{путь}} в тексте и атрибутах,\n * <sc-for list=\"{{массив}}\" as=\"x\">, <sc-if value=\"{{условие}}\">, onClick/onInput=\"{{функция}}\"\n * и класс Component extends DCLogic { renderVals() } из <script type=\"text/x-dc\">.\n * Общие значения шапки (вход, аватар, меню) доступны как {{K.*}}.\n */\n(function () {\n  'use strict';\n\n  var comp = null, root = null, tpl = null, queued = false;\n\n  function DCLogic(props) { this.props = props || {}; this.state = {}; }\n  DCLogic.prototype.setState = function (patch) {\n    Object.assign(this.state, typeof patch === 'function' ? patch(this.state) : patch);\n    schedule();\n  };\n  window.DCLogic = DCLogic;\n\n  function schedule() {\n    if (queued) return;\n    queued = true;\n    (window.requestAnimationFrame || setTimeout)(function () { queued = false; render(); });\n  }\n  window.KomoriRender = schedule;\n\n  // ---------- значения ----------\n  function lookup(path, scopes) {\n    var parts = path.trim().split('.');\n    for (var i = scopes.length - 1; i >= 0; i--) {\n      if (scopes[i] && Object.prototype.hasOwnProperty.call(scopes[i], parts[0])) {\n        var v = scopes[i][parts[0]];\n        for (var j = 1; j < parts.length; j++) v = v == null ? undefined : v[parts[j]];\n        return v;\n      }\n    }\n    return undefined;\n  }\n  var HOLE = /\\{\\{\\s*([A-Za-z_$][\\w$.]*)\\s*\\}\\}/g;\n  function interpolate(str, scopes) {\n    return str.replace(HOLE, function (_, p) { var v = lookup(p, scopes); return v == null ? '' : String(v); });\n  }\n  function single(str) { var m = /^\\s*\\{\\{\\s*([A-Za-z_$][\\w$.]*)\\s*\\}\\}\\s*$/.exec(str || ''); return m && m[1]; }\n\n  // ---------- построение DOM ----------\n  function build(node, scopes, out) {\n    if (node.nodeType === 3) { // текст\n      out.push(document.createTextNode(node.nodeValue.indexOf('{{') >= 0 ? interpolate(node.nodeValue, scopes) : node.nodeValue));\n      return;\n    }\n    if (node.nodeType !== 1) return;\n    var tag = node.tagName;\n    if (tag === 'TEMPLATE' && node.hasAttribute('data-sc')) {\n      var kind = node.getAttribute('data-sc');\n      if (kind === 'for') {\n        var list = lookup(single(node.getAttribute('list')) || '', scopes) || [];\n        var as = node.getAttribute('as') || 'item';\n        for (var i = 0; i < list.length; i++) {\n          var sc = {}; sc[as] = list[i]; sc[as + 'Index'] = i;\n          buildChildren(node.content, scopes.concat([sc]), out);\n        }\n      } else if (kind === 'if') {\n        if (lookup(single(node.getAttribute('value')) || '', scopes)) buildChildren(node.content, scopes, out);\n      }\n      return;\n    }\n    var el = node.cloneNode(false);\n    var attrs = node.attributes;\n    for (var a = attrs.length - 1; a >= 0; a--) {\n      var name = attrs[a].name, val = attrs[a].value;\n      if (name.indexOf('hint-') === 0) { el.removeAttribute(name); continue; }\n      if (/^on[a-z]+$/.test(name)) {\n        el.removeAttribute(name);\n        var fn = lookup(single(val) || '', scopes);\n        if (typeof fn === 'function') el.addEventListener(name.slice(2), fn);\n        continue;\n      }\n      if (val.indexOf('{{') >= 0) {\n        var v = interpolate(val, scopes);\n        // булевы атрибуты: \"false\" или пусто — убрать атрибут\n        if (/^(checked|disabled|selected|readonly|required|hidden)$/.test(name) && (v === 'false' || v === '')) el.removeAttribute(name);\n        else el.setAttribute(name, v);\n      }\n    }\n    var src = tag === 'TEMPLATE' ? node.content : node;\n    var kids = [];\n    buildChildren(src, scopes, kids);\n    for (var k = 0; k < kids.length; k++) el.appendChild(kids[k]);\n    if (tag === 'TEXTAREA') el.value = el.textContent;\n    if (tag === 'INPUT' && el.hasAttribute('checked')) el.checked = true;\n    out.push(el);\n  }\n  function buildChildren(parent, scopes, out) {\n    for (var c = parent.firstChild; c; c = c.nextSibling) build(c, scopes, out);\n  }\n\n  // ---------- отрисовка ----------\n  function render() {\n    if (!comp) return;\n    var vals = comp.renderVals ? comp.renderVals() : {};\n    var K = window.KomoriBase ? window.KomoriBase() : {};\n    var active = document.activeElement, focusId = active && active.id, selS, selE;\n    try { selS = active.selectionStart; selE = active.selectionEnd; } catch (e) {}\n    var out = [];\n    buildChildren(tpl.content, [{ K: K }, vals], out);\n    root.replaceChildren.apply(root, out);\n    if (focusId) {\n      var f = document.getElementById(focusId);\n      if (f) { f.focus(); try { if (selS != null) f.setSelectionRange(selS, selE); } catch (e) {} }\n    }\n  }\n\n  function start() {\n    root = document.querySelector('x-dc');\n    tpl = document.getElementById('komori-tpl');\n    if (!root || !tpl) return;\n    var helmet = tpl.content.querySelector('helmet');\n    if (helmet) { while (helmet.firstChild) document.head.appendChild(helmet.firstChild); helmet.remove(); }\n    root.style.display = 'block';\n    var script = document.querySelector('script[data-dc-script]');\n    var Component = script ? new Function('DCLogic', script.textContent + '\\n;return Component;')(DCLogic) : DCLogic;\n    comp = new Component({});\n    render();\n    if (typeof comp.mounted === 'function') comp.mounted();\n  }\n\n  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start); else start();\n})();\n";
// Komori — сайт сервера на Cloudflare Workers.
// Страницы, вход через Discord (OAuth2 + проверка ботом, что игрок есть на сервере Komori),
// профили игроков в KV, статистика онлайна.
//
// Нужно в настройках Worker'а:
//   KV-привязка  SITE                    — хранилище пользователей и сессий
//   Секреты      DISCORD_CLIENT_SECRET   — OAuth2 → Client Secret приложения
//                DISCORD_BOT_TOKEN       — Bot → Token
//   (необязательно) ROLE_BADGES — JSON {"<id роли>":{"label":"VIP","color":"#FFC857"}, ...}


// ===== настройки (не секретные) =====
